#                             语言（新加）
# ==================================================================

# 新加：游戏可以用 中文 或者 西班牙语（卡斯蒂利亚语 = castellano）玩。游戏一开始先问，之后在战斗的 [0] 设置 里也能换
# 做法：显示给玩家看的文字都写两遍：文("中文", "西班牙语")，按现在的语言选一个
#       游戏里面判断、存档用的名字（职业、护符、药水、天赋、章节、怪物……）一直都是中文，只有显示的时候才翻译（看 名()）
#       这样不管用哪种语言玩，存档都是一样的，中途换语言也不会坏
# 以后加新的文字：写成 文("中文", "西班牙语")；加新的名字（新怪物、新天赋……）：在下面的 名字翻译表 里加一行
# 注意：文() 要在玩的时候才调用（函数里面），不能直接写在文件最外面的列表里（那时候还没选语言）
#       所以剧情那些写在外面的列表（章节开场、结局文字列表……）旁边都另外有一个 _西班牙语 的列表，一一对应
语言 = "中文"                  # "中文" / "西班牙语"

def 文(中文, 西班牙语):
    # 新加：按现在的语言，返回其中一段文字
    if 语言 == "西班牙语":
        return 西班牙语
    return 中文

def 名(名字):
    # 新加：显示用：把游戏里的中文名字翻译成现在的语言（中文 → 原样；西班牙语 → 去 名字翻译表 里找）
    # 名字翻译表 里没有的（忘了加）就原样显示，不会报错
    if 语言 == "中文":
        return 名字
    for 一对 in 名字翻译表:
        if 一对[0] == 名字:
            return 一对[1]
    return 名字

def 名单(名字列表):
    # 新加：显示用：一串名字翻译好再连起来。中文用顿号：尸狗、愤怒；西班牙语用逗号：Alegría, Ira
    翻译好的 = []
    for 名字 in 名字列表:
        翻译好的.append(名(名字))
    return 文("、", ", ").join(翻译好的)

def 选择语言():
    # 新加：问玩家用哪种语言（游戏一开始、战斗的设置里都会用）。两种语言都写上，不管现在是哪种都看得懂
    global 语言
    while True:
        print("\n========== 语言 / Idioma ==========")
        print("[1] 中文")
        print("[2] Castellano (español)")
        回答 = 读输入("请选择 / Elige: ").strip()
        if 回答 == "1":
            语言 = "中文"
            break
        if 回答 == "2":
            语言 = "西班牙语"
            break
        print(">> 请输入 1 或 2 / Escribe 1 o 2")
    清屏()
    if 行动详情_角色 != "" and len(当前技能等级) > 0:
        更新行动详情()          # 技能说明是按语言生成的（看 更新行动详情()），换了语言要重新生成一次
    print(文(">> 语言：中文", ">> Idioma: castellano"))

