def 开放的职业():
    # 新加：现在开新游戏能选的职业 = 开放职业 + 解锁了的职业（坦克：打完第一章）
    #       已打完的章节 写在下面的 章节 那一部分（永久进度），选职业的时候已经读好了
    能选 = list(开放职业)                  # list() = 复制一份，不会改到 开放职业
    if 坦克解锁章节 in 已打完的章节 and "坦克" not in 能选:
        能选.append("坦克")
    return 能选
