# 普攻：造成50(~100)%伤害并获得20点能量|技能1：造成75(~150)%伤害并消耗25点能量。该伤害可暴击|技能2：提升50(~100)点暴击伤害,暴击后移除提升。
# 大招：造成100(~200)%伤害并消耗25点能量。该伤害可暴击|被动1：若攻击没触发暴击,则提升10(~20)点暴击率,最多提升3次。暴击后移除提升|被动2：触发暴击时,获得1(~5)枚金币
# 准进阶被动：还没做（刺客还不能转职）
def 商人():
    global 最大生命值, 基础攻击力, 基础防御力, 基础命中率, 基础暴击率, 基础暴击伤害, 基础幸运, 当前持有金币, 最大持有护符的数量, 额外获得金币加成
