# 新加：准进阶被动、转职的数值都放在这里，测试的时候觉得太强/太弱就改这里
准进阶被动解锁花费 = 30               # 解锁即满级（原来解锁被动3也是30G）
准进阶被动_攻击力提升 = 30            # 战士的准进阶被动：基础攻击力 +30%
准进阶被动_防御力提升 = 30            # 新加：坦克的准进阶被动：基础防御力 +30%
转职后保留准进阶加成 = False          # False：转职以后准进阶被动进阶成了进阶被动，这 +30% 就没了；True：转职以后也一直 +30%
转职条件_另一个被动低于 = 3           # 狂战士：被动1满级 + 被动2低于lv3；重装骑士：被动2满级 + 被动1低于lv3（坦克的也是低于lv3）
突破花费 = 50                         # 修改：所有突破都是50G（原来跟着升级的公式：30G、45G）
突破前要失败几次 = 3                  # 新加：满级的被动连续点升级，先提示3次"已升满"，连续第4次条件够了才会发现突破（像空洞骑士的护符过载）

# 新加：所有隐藏的突破（转职）。五个列表一一对应，一行 = 一条路
#   哪个职业 → 在锻炼里一直按哪个键（满级的那个）→ 突破成什么 → 那个键的技能要满级 → 哪个技能要低于lv3
#   技能的编号：0 普攻 / 1 技能1 / 2 技能2 / 3 大招 / 4 被动1 / 5 被动2（跟 修炼场() 里的一样）
#   坦克的两个职业都有两条路（被动 或者 技能），满足哪一条都行：按的是哪个键，就看哪一条
突破_原职业 = ["战士", "战士", "坦克", "坦克", "坦克", "坦克"]
突破_按键 = ["5", "6", "5", "2", "6", "3"]
突破_新职业 = ["狂战士", "重装骑士", "前线装甲", "前线装甲", "荆棘盾兵", "荆棘盾兵"]
突破_要满级 = [4, 5, 4, 1, 5, 2]             # 被动1 / 被动2 / 被动1 / 技能1 / 被动2 / 技能2
突破_要低于3级 = [5, 4, 5, 2, 4, 1]          # 被动2 / 被动1 / 被动2 / 技能2 / 被动1 / 技能1

# 转职时的数值改动（%）：只改 最大生命值、基础攻击力、基础防御力（护符加的 额外X加成 不变）
狂战士_生命值改动 = 100
狂战士_攻击力改动 = 25
狂战士_防御力改动 = -50
重装骑士_生命值改动 = -25
重装骑士_攻击力改动 = 30
重装骑士_防御力改动 = 30
荆棘盾兵_生命值改动 = 20              # 新加：荆棘盾兵的进阶被动：防御力 +25%，生命值 +20%，攻击力 -20%
荆棘盾兵_攻击力改动 = -20
荆棘盾兵_防御力改动 = 25
前线装甲_生命值改动 = -20             # 新加：前线装甲的进阶被动：防御力 +50%，攻击力 -20%，生命值 -20%
前线装甲_攻击力改动 = -20
前线装甲_防御力改动 = 50

# 技能里不跟着等级变的数值（战斗、行动详情 都用这里的）
战士_增益最多层数 = 3                 # 新加：战士技能1，【增益】最多叠3层
狂战士_技能1消耗生命值 = 30           # 技能1：消耗30%当前生命值
狂战士_技能1持续回合 = 3              # 使用技能1算第1回合，所以实际只加成接下来的2次攻击
狂战士_技能2消耗能量 = 10
狂战士_被动分界线 = 50                # 被动1：生命值低于50%（修改：被动2 不看生命值了，只有被动1 用）
狂战士_进阶每缺少生命值 = 10          # 进阶被动：每缺少10点生命值 → +1点攻击力
狂战士_进阶增加攻击力 = 1
重装骑士_防御形态_攻击力 = -50        # 防御形态：攻击力 -50%
重装骑士_防御形态_防御力 = 50         # 防御形态：防御力 +50%
重装骑士_攻击形态_攻击力 = 50         # 攻击形态：攻击力 +50%
重装骑士_攻击形态_防御力 = -50        # 攻击形态：防御力 -50%
重装骑士_技能1消耗能量 = 10           # 两种形态的技能1都消耗10点能量
重装骑士_大招持续回合 = 3             # 防御形态的大招
# 新加：坦克、荆棘盾兵、前线装甲
护盾挡住算几成 = 50                   # 回敬、荆棘盾兵被动1 看「受到的伤害」的时候，被护盾挡住的那部分只算50%
坦克_技能1消耗能量 = 15
坦克_技能2减伤 = 35                   # 技能2：敌人下一回合的伤害 -35%（固定，不跟等级变）
坦克_技能2消耗能量 = 25
荆棘盾兵_技能1消耗能量 = 20
荆棘盾兵_技能2最多层数 = 2
荆棘盾兵_技能2持续 = 2                # 持续3回合（用技能2算第1回合）= 实际挡接下来敌人的2个回合（敌人的回合打完才倒数）
荆棘盾兵_被动1触发线 = 20             # 被动1：一下受到的伤害 > 当前生命值的20%
荆棘盾兵_被动1冷却回合 = 3            # 冷却3回合（触发的回合算第1回合）= 接下来敌人的2个回合不会再触发
前线装甲_技能1护盾 = 20               # 技能1：获得20%防御力的护盾（固定，不跟等级变）
前线装甲_技能1消耗能量 = 25
前线装甲_每点护盾提升 = 1             # 技能1 出手的时候护盾还在：每1点护盾 伤害+1%
前线装甲_每次蓄力伤害 = 25            # 技能2 蓄力以后放出去：每次蓄力 +25%防御力的伤害
前线装甲_大招蓄力次数 = 2             # 大招以后用技能2：一次蓄2次力
前线装甲_被动1最多层数 = 5

def 有准进阶被动():
    # 新加：现在只有战士、坦克（还有它们转职以后的职业）有准进阶被动，其他职业的还没做
    # 修改：加了坦克
    return 行动详情_角色 == "战士" or 行动详情_角色 == "坦克" or 行动详情_角色 in 进阶职业

def 准进阶攻击力提升():
    # 新加：准进阶被动让基础攻击力提升了多少%（更新最终数值() 里用）
    # 修改：只算战士那一边的（狂战士、重装骑士）
    if not 准进阶被动解锁:
        return 0
    if 行动详情_角色 == "战士":
        return 准进阶被动_攻击力提升
    if 行动详情_角色 in 进阶职业 and 进阶职业的原职业[进阶职业.index(行动详情_角色)] == "战士" and 转职后保留准进阶加成:
        return 准进阶被动_攻击力提升
    return 0

def 准进阶防御力提升():
    # 新加：坦克的准进阶被动让基础防御力提升了多少%（跟上面一样，只是坦克那一边的：荆棘盾兵、前线装甲）
    if not 准进阶被动解锁:
        return 0
    if 行动详情_角色 == "坦克":
        return 准进阶被动_防御力提升
    if 行动详情_角色 in 进阶职业 and 进阶职业的原职业[进阶职业.index(行动详情_角色)] == "坦克" and 转职后保留准进阶加成:
        return 准进阶被动_防御力提升
    return 0

def 找突破(按键):
    # 新加：现在的职业在锻炼里按这个键（满级的那个），对应的是哪一条突破（在 突破_X 里的位置）。没有 → -1
    for 位置 in range(len(突破_原职业)):
        if 突破_原职业[位置] == 行动详情_角色 and 突破_按键[位置] == 按键:
            return 位置
    return -1

def 能转职(位置):
    # 新加：现在能不能走 突破_X 里的这一条路突破（位置 从 找突破() 来）
    # 要同时满足：还是原来的职业 + 准进阶被动已解锁 + 那个技能满级 + 另一个低于lv3 + 有50G（修改：加上了钱）
    # 修改：原来传的是新职业（"狂战士" / "重装骑士"）；坦克的职业有两条路，所以改成传 突破_X 里的位置
    if 位置 == -1 or 行动详情_角色 != 突破_原职业[位置] or not 准进阶被动解锁 or 当前持有金币 < 突破花费:
        return False
    技能等级列表 = [普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级]
    return 技能等级列表[突破_要满级[位置]] == 5 and 技能等级列表[突破_要低于3级[位置]] < 转职条件_另一个被动低于

def 满级再升级(按键, 连续次数):
    # 新加：锻炼里，已经满级的 技能1/技能2/被动1/被动2 还想再升级（隐藏的突破就在这里）
    # 修改：原来叫 满级被动再升级(第几个被动, 连续次数)，只看被动；坦克的技能1、技能2 也能突破，所以改成传按的键（"2" "3" "5" "6"）
    # 连续次数 = 这是连续第几次按这个满级的技能（锻炼() 里数的，按了别的就重新数）
    # 修改：改成永久解锁（像以撒解锁角色），而且不问也不提示：
    #   这个存档还没解锁过这个职业：前3次提示"已升满"，连续第4次（以后）条件够了 → 显示「狂战士已解锁」+ 直接转职（记进永久进度）
    #   以前的局已经解锁过：条件够了，点一次就直接转职，什么都不显示
    #   条件不够：跟普通的满级提示一模一样（不告诉你差什么）
    #   原来的 确认转职()（问要不要转）、转职条件文字()（显示条件）、对错() 都删掉了
    global 当前持有金币
    位置 = 找突破(按键)
    已解锁 = 位置 != -1 and 突破_新职业[位置] in 已解锁的职业

    # 能转职() 里也会看是不是原来的职业：已经转职了（或者别的职业、战士按技能1/技能2）也是走这里，显示"已升满"
    if not 能转职(位置) or (not 已解锁 and 连续次数 <= 突破前要失败几次):
        满级提示(按键)                    # 跟普通的满级提示一模一样，不会被看出来
        return

    新职业 = 突破_新职业[位置]
    当前持有金币 -= 突破花费
    if not 已解锁:
        解锁职业(新职业)                  # 第一次：显示「狂战士已解锁」
        保存进度(当前存档编号)            # 马上存进度（后面死了也不会没）
    转职(新职业, False)                   # 不显示「突破成功」那些

def 满级提示(按键):
    # 新加：锻炼里满级的提示（原来写在 锻炼() 里面，满级再升级() 也要用一模一样的）
    if 按键 == "2":
        print(文(">> 技能1已升满!", ">> ¡La Habilidad 1 ya está al máximo!"))
    elif 按键 == "3":
        print(文(">> 技能2已升满!", ">> ¡La Habilidad 2 ya está al máximo!"))
    elif 按键 == "5":
        print(文(">> 被动1已升满!", ">> ¡La Pasiva 1 ya está al máximo!"))
    else:
        print(文(">> 被动2已升满!", ">> ¡La Pasiva 2 ya está al máximo!"))

def 转职数值改动(新职业):
    # 新加：返回 新职业 的 最大生命值、攻击力、防御力 改动（%），一次返回三个数
    # 修改：加了 荆棘盾兵、前线装甲
    if 新职业 == "狂战士":
        return 狂战士_生命值改动, 狂战士_攻击力改动, 狂战士_防御力改动
    if 新职业 == "荆棘盾兵":
        return 荆棘盾兵_生命值改动, 荆棘盾兵_攻击力改动, 荆棘盾兵_防御力改动
    if 新职业 == "前线装甲":
        return 前线装甲_生命值改动, 前线装甲_攻击力改动, 前线装甲_防御力改动
    return 重装骑士_生命值改动, 重装骑士_攻击力改动, 重装骑士_防御力改动

def 转职(新职业, 显示 = True):
    # 新加：战士 → 狂战士 / 重装骑士，坦克 → 荆棘盾兵 / 前线装甲（在锻炼里突破的时候调用，钱已经扣好了）
    # 技能和被动的等级不用动，更新技能() 会换成 新职业 的数值表和说明
    # 修改：多了 显示：锻炼里突破的时候传 False（不提示）；控制台的 class 还是会显示数值变化
    global 行动详情_角色, 最大生命值, 基础攻击力, 基础防御力, 当前生命值
    旧生命值 = 当前生命值
    旧生命值上限 = 生命值上限()
    旧攻击力 = 当前攻击力
    旧防御力 = 当前防御力

    生命值改动, 攻击力改动, 防御力改动 = 转职数值改动(新职业)
    最大生命值 = 最大生命值 * (1 + 生命值改动 / 100)
    基础攻击力 = 基础攻击力 * (1 + 攻击力改动 / 100)
    基础防御力 = 基础防御力 * (1 + 防御力改动 / 100)
    行动详情_角色 = 新职业

    # 生命值上限变了多少，当前生命值也跟着变多少（转职不能反悔，所以不像翡翠那样只改上限）
    # 例：狂战士 80/100 → 180/200；重装骑士 80/100 → 55/75。最少留1点生命值，转职不会把人转死
    当前生命值 = max(1, 当前生命值 + (生命值上限() - 旧生命值上限))

    更新最终数值()          # 重新算 当前攻击力、当前防御力（准进阶被动的 +30% 也是在这里去掉的）
    更新技能()              # 换成 新职业 的数值表和说明
    if not 显示:
        return
    print(文(f"\n★ 突破成功！你转职成了【{新职业}】！ ★",
             f"\n★ ¡Evolución completada! ¡Ahora eres【{名(新职业)}】! ★"))
    print(文(f">> 生命值:【{生命值文字(旧生命值)}/{round(旧生命值上限)} >>> {生命值文字(当前生命值)}/{round(生命值上限())}】",
             f">> Vida:【{生命值文字(旧生命值)}/{round(旧生命值上限)} >>> {生命值文字(当前生命值)}/{round(生命值上限())}】") +     # 修改：round → 生命值文字（还活着最少显示1）
          文(f"|攻击力:【{round(旧攻击力)} >>> {round(当前攻击力)}】|防御力:【{round(旧防御力)} >>> {round(当前防御力)}】",
             f"|Ataque:【{round(旧攻击力)} >>> {round(当前攻击力)}】|Defensa:【{round(旧防御力)} >>> {round(当前防御力)}】"))

def 锻炼():
    global 行动详情, 当前技能等级, 普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级, 被动1解锁, 被动2解锁, 准进阶被动解锁, 当前持有金币
    满级连续次数 = 0            # 新加：连续按了几次同一个满级的被动（中间按了别的、离开锻炼，都要重新数）
    连续按的是 = ""             # 新加：连续按的是哪个："5"（被动1）/ "6"（被动2）/ "2"（技能1）/ "3"（技能2）（修改：坦克的技能也能突破）

    while True:
        print(文(f"当前持有金币: [{当前持有金币}G]", f"Monedas: [{当前持有金币}G]"))
        print(文("可升级以下技能:", "Puedes mejorar estas habilidades:"))

        if 普攻等级 != 5:
            print(文(f"[1] 普攻 (lv {普攻等级} >>> lv {普攻等级 + 1}) 花费[{5 + (普攻等级 * 5)}G]",
                     f"[1] Ataque básico (lv {普攻等级} >>> lv {普攻等级 + 1}) cuesta [{5 + (普攻等级 * 5)}G]"))
        else:
            print(文("[/] 普攻 (满级)", "[/] Ataque básico (al máximo)"))

        if 技能1等级 != 5:
            print(文(f"[2] 技能1 (lv {技能1等级} >>> lv {技能1等级 + 1} 花费[{5 + (技能1等级 * 5)}G])",
                     f"[2] Habilidad 1 (lv {技能1等级} >>> lv {技能1等级 + 1} cuesta [{5 + (技能1等级 * 5)}G])"))
        else:
            print(文("[/] 技能1 (满级)", "[/] Habilidad 1 (al máximo)"))

        if 技能2等级 != 5:
            print(文(f"[3] 技能2 (lv {技能2等级} >>> lv {技能2等级 + 1} 花费[{5 + (技能2等级 * 5)}G])",
                     f"[3] Habilidad 2 (lv {技能2等级} >>> lv {技能2等级 + 1} cuesta [{5 + (技能2等级 * 5)}G])"))
        else:
            print(文("[/] 技能2 (满级)", "[/] Habilidad 2 (al máximo)"))

        if 大招等级 != 5:
            print(文(f"[4] 大招 (lv {大招等级} >>> lv {大招等级 + 1} 花费[{5 + (大招等级 * 5)}G])",
                     f"[4] Definitiva (lv {大招等级} >>> lv {大招等级 + 1} cuesta [{5 + (大招等级 * 5)}G])"))
        else:
            print(文("[/] 大招 (满级)", "[/] Definitiva (al máximo)"))

        if not 被动1解锁:
            print(文("[5] 被动1 (未解锁 >>> lv 1 花费[10G])", "[5] Pasiva 1 (bloqueada >>> lv 1 cuesta [10G])"))
        elif 被动1等级 != 5:
            print(文(f"[5] 被动1 (lv {被动1等级} >>> lv {被动1等级 + 1} 花费[{5 + (被动1等级 * 5)}G])",
                     f"[5] Pasiva 1 (lv {被动1等级} >>> lv {被动1等级 + 1} cuesta [{5 + (被动1等级 * 5)}G])"))
        else:
            print(文("[/] 被动1 (满级)", "[/] Pasiva 1 (al máximo)"))             # 修改：满级就一直这样显示（还是可以按5，隐藏的突破在 满级再升级() 里）

        if not 被动2解锁:
            print(文("[6] 被动2 (未解锁 >>> lv 1 花费[20G])", "[6] Pasiva 2 (bloqueada >>> lv 1 cuesta [20G])"))
        elif 被动2等级 != 5:
            print(文(f"[6] 被动2 (lv {被动2等级} >>> lv {被动2等级 + 1} 花费[{10 + (被动2等级 * 7)}G])",
                     f"[6] Pasiva 2 (lv {被动2等级} >>> lv {被动2等级 + 1} cuesta [{10 + (被动2等级 * 7)}G])"))
        else:
            print(文("[/] 被动2 (满级)", "[/] Pasiva 2 (al máximo)"))             # 修改：同上

        # 修改：被动3 → 准进阶被动（解锁即满级）。转职以后叫 进阶被动，不用再升级
        if not 有准进阶被动():
            print(文("[/] 准进阶被动 (敬请期待)", "[/] Pasiva pre-avanzada (próximamente)"))
        elif 行动详情_角色 in 进阶职业:
            print(文(f"[/] 进阶被动 (已转职成【{行动详情_角色}】)",
                     f"[/] Pasiva avanzada (ya eres【{名(行动详情_角色)}】)"))
        elif not 准进阶被动解锁:
            print(文(f"[7] 准进阶被动 (未解锁 >>> 满级 花费[{准进阶被动解锁花费}G])",
                     f"[7] Pasiva pre-avanzada (bloqueada >>> al máximo cuesta [{准进阶被动解锁花费}G])"))
        else:
            print(文("[/] 准进阶被动 (满级)", "[/] Pasiva pre-avanzada (al máximo)"))

        # 修改：去掉了转职条件的显示（不提示，要自己发现、自己记住）

        print(文("[0] 返回", "[0] Volver"))

        选择 = 输入(文("请选择: ", "Elige: "))              # 修改：input → 输入（输完马上清屏）

        # 新加：数一数是不是在连续按同一个满级的被动（隐藏的突破要连续按，按了别的就从头数）
        # 修改：满级的技能1、技能2 也算（坦克的突破有一条路是技能）
        按的是满级被动 = (选择 == "5" and 被动1等级 == 5) or (选择 == "6" and 被动2等级 == 5) or \
                         (选择 == "2" and 技能1等级 == 5) or (选择 == "3" and 技能2等级 == 5)
        if 按的是满级被动 and 选择 == 连续按的是:
            满级连续次数 += 1
        elif 按的是满级被动:
            满级连续次数 = 1
            连续按的是 = 选择
        else:
            满级连续次数 = 0
            连续按的是 = ""

        if 选择 == "0":
            break

        elif 选择 == "1":
            花费 = 5 + (普攻等级 * 5)
            if 普攻等级 == 5:
                print(文(">> 普攻已升满!", ">> ¡El ataque básico ya está al máximo!"))
            elif 当前持有金币 < 花费:
                print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
            else:
                当前持有金币 -= 花费
                普攻等级 += 1
                print(文(f">> 普攻成功升级到 lv {普攻等级}!", f">> ¡Ataque básico mejorado a lv {普攻等级}!"))
                更新技能()

        elif 选择 == "2":
            花费 = 5 + (技能1等级 * 5)
            if 技能1等级 == 5:
                满级再升级("2", 满级连续次数)        # 修改：满级了还想升级 → 可能会发现隐藏的突破（坦克 → 前线装甲）
            elif 当前持有金币 < 花费:
                print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
            else:
                当前持有金币 -= 花费
                技能1等级 += 1
                print(文(f">> 技能1成功升级到 lv {技能1等级}!", f">> ¡Habilidad 1 mejorada a lv {技能1等级}!"))
                更新技能()

        elif 选择 == "3":
            花费 = 5 + (技能2等级 * 5)
            if 技能2等级 == 5:
                满级再升级("3", 满级连续次数)        # 修改：同上（坦克 → 荆棘盾兵）
            elif 当前持有金币 < 花费:
                print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
            else:
                当前持有金币 -= 花费
                技能2等级 += 1
                print(文(f">> 技能2成功升级到 lv {技能2等级}!", f">> ¡Habilidad 2 mejorada a lv {技能2等级}!"))
                更新技能()

        elif 选择 == "4":
            花费 = 5 + (大招等级 * 5)
            if 大招等级 == 5:
                print(文(">> 大招已升满!", ">> ¡La Definitiva ya está al máximo!"))
            elif 当前持有金币 < 花费:
                print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
            else:
                当前持有金币 -= 花费
                大招等级 += 1
                print(文(f">> 大招成功升级到 lv {大招等级}!", f">> ¡Definitiva mejorada a lv {大招等级}!"))
                更新技能()

        elif 选择 == "5":
            if not 被动1解锁:
                if 当前持有金币 < 10:
                    print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
                else:
                    当前持有金币 -= 10
                    被动1解锁 = True
                    被动1等级 = 1
                    print(文(">> 被动1已成功解锁!", ">> ¡Pasiva 1 desbloqueada!"))
                    更新技能()          # 修改：解锁以后也要更新，不然被动的数值和说明还是0级的
            elif 被动1等级 < 5:
                花费 = 5 + (被动1等级 * 5)
                if 当前持有金币 < 花费:
                    print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
                else:
                    当前持有金币 -= 花费
                    被动1等级 += 1
                    print(文(f">> 被动1成功升级到 lv {被动1等级}!", f">> ¡Pasiva 1 mejorada a lv {被动1等级}!"))
                    更新技能()
            else:
                满级再升级("5", 满级连续次数)        # 修改：满级了还想升级 → 可能会发现隐藏的突破（战士 → 狂战士，坦克 → 前线装甲）

        elif 选择 == "6":
            if not 被动2解锁:
                if 当前持有金币 < 20:
                    print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
                else:
                    当前持有金币 -= 20
                    被动2解锁 = True
                    被动2等级 = 1
                    print(文(">> 被动2已成功解锁!", ">> ¡Pasiva 2 desbloqueada!"))
                    更新技能()          # 修改：同上
            elif 被动2等级 < 5:
                花费 = 10 + (被动2等级 * 7)
                if 当前持有金币 < 花费:
                    print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
                else:
                    当前持有金币 -= 花费
                    被动2等级 += 1
                    print(文(f">> 被动2成功升级到 lv {被动2等级}!", f">> ¡Pasiva 2 mejorada a lv {被动2等级}!"))
                    更新技能()
            else:
                满级再升级("6", 满级连续次数)        # 修改：同上（战士 → 重装骑士，坦克 → 荆棘盾兵）

        elif 选择 == "7":
            # 修改：被动3 → 准进阶被动（解锁即满级，没有 lv2~lv5）
            if not 有准进阶被动():
                print(文(">> 准进阶被动还没做好捏~(￣▽￣)~*",
                         ">> La pasiva pre-avanzada todavía no está hecha, jeje~(￣▽￣)~*"))
            elif 行动详情_角色 in 进阶职业:
                print(文(">> 已经转职了，进阶被动不用再升级!",
                         ">> ¡Ya has evolucionado, la pasiva avanzada no se mejora más!"))
            elif 准进阶被动解锁:
                print(文(">> 准进阶被动已满级!", ">> ¡La pasiva pre-avanzada ya está al máximo!"))
            elif 当前持有金币 < 准进阶被动解锁花费:
                print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
            else:
                当前持有金币 -= 准进阶被动解锁花费
                准进阶被动解锁 = True
                print(文(">> 准进阶被动已成功解锁!", ">> ¡Pasiva pre-avanzada desbloqueada!"))          # 修改：去掉了「（解锁即满级）」
                更新最终数值()          # 基础攻击力（坦克是基础防御力）+30%，要重新算
                更新技能()

def 买护符(商店的护符):
    # 修改：原来是空的。商店的护符 是进商店的时候抽好的（看 商店()），买走的会从列表里删掉
    # 价格看品质（商店护符价格）。护符满了：先选一个扔掉（或者不买了），确定能放进去才扣钱
    global 当前持有金币
    while True:
        print(文(f"\n当前持有金币: [{当前持有金币}G]  护符【{当前持有护符的数量}/{最大持有护符的数量}】",
                 f"\nMonedas: [{当前持有金币}G]  Amuletos【{当前持有护符的数量}/{最大持有护符的数量}】"))
        if len(商店的护符) == 0:
            print(文("护符都卖光了~", "¡Ya no quedan amuletos~!"))
        for 编号 in range(len(商店的护符)):
            print(文(f"[{编号 + 1}] {护符说明(商店的护符[编号])} 花费[{护符价格(商店的护符[编号])}G]",
                     f"[{编号 + 1}] {护符说明(商店的护符[编号])} cuesta [{护符价格(商店的护符[编号])}G]"))
        print(文("[0] 返回", "[0] Volver"))
        选择 = 输入数字(文("请选择: ", "Elige: "), 0, len(商店的护符))
        if 选择 == 0:
            break
        护符 = 商店的护符[选择 - 1]
        价格 = 护符价格(护符)
        if 当前持有金币 < 价格:
            print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
        elif 收下护符(护符):                            # 收下了才扣钱（护符满了又选了不要 → 不扣）
            当前持有金币 -= 价格
            商店的护符.pop(选择 - 1)
            print(文(f">> 买下了【{护符说明(护符)}】！（当前持有金币: {当前持有金币}G）",
                     f">> ¡Has comprado【{护符说明(护符)}】! (Monedas: {当前持有金币}G)"))

def 买物品(商店的消耗品):
    # 修改：原来是空的。现在卖药水：商店的消耗品 是进商店的时候抽好的（看 商店()），买走的会从列表里删掉
    global 当前持有金币, 当前持有消耗品的列表
    while True:
        print(文(f"\n当前持有金币: [{当前持有金币}G]  身上的消耗品【{len(当前持有消耗品的列表)}】",
                 f"\nMonedas: [{当前持有金币}G]  Consumibles que llevas【{len(当前持有消耗品的列表)}】"))
        if len(商店的消耗品) == 0:
            print(文("药水都卖光了~", "¡Ya no quedan pociones~!"))
        for 编号 in range(len(商店的消耗品)):
            print(文(f"[{编号 + 1}] {药水说明(商店的消耗品[编号])} 花费[{药水价格(商店的消耗品[编号])}G]",
                     f"[{编号 + 1}] {药水说明(商店的消耗品[编号])} cuesta [{药水价格(商店的消耗品[编号])}G]"))
        print(文("[0] 返回", "[0] Volver"))
        选择 = 输入数字(文("请选择: ", "Elige: "), 0, len(商店的消耗品))
        if 选择 == 0:
            break
        药水 = 商店的消耗品[选择 - 1]
        价格 = 药水价格(药水)
        if 当前持有金币 < 价格:
            print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
        else:
            当前持有金币 -= 价格
            当前持有消耗品的列表.append(商店的消耗品.pop(选择 - 1))
            print(文(f">> 买下了【{药水说明(药水)}】！（当前持有金币: {当前持有金币}G）",
                     f">> ¡Has comprado【{药水说明(药水)}】! (Monedas: {当前持有金币}G)"))

def 商店():
    global 行动详情, 当前技能等级, 普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级, 被动1解锁, 被动2解锁, 准进阶被动解锁, 当前持有金币

    # 新加：每次来商店先进货：护符、药水都是随机的。这一次逛商店一直是这些（买走了就没了，下次来商店重新进货）
    商店的护符 = []
    for 第几个 in range(商店护符数量):
        商店的护符.append(抽取护符(商店护符品质权重))
    商店的消耗品 = []
    for 第几个 in range(商店药水数量):
        商店的消耗品.append(抽取药水())

    while True:
        print(文(f"\n当前持有金币: [{当前持有金币}G]", f"\nMonedas: [{当前持有金币}G]"))
        print(文("[1] 购买物品", "[1] Comprar objetos"))
        print(文("[2] 购买护符", "[2] Comprar amuletos"))
        print(文("[3] 锻炼自身", "[3] Entrenar"))
        print(文("[0] 退出", "[0] Salir"))

        商店行动 = 输入(文("请选择: ", "Elige: "))          # 修改：input → 输入（输完马上清屏）
        if 商店行动 == "1":
            买物品(商店的消耗品)        # 修改：把进好的货传进去（是同一个列表：在里面买走了，这里的列表也会少）
        elif 商店行动 == "2":
            买护符(商店的护符)
        elif 商店行动 == "3":
            锻炼()
        elif 商店行动 == "0":
            print(文("已退出商店。", "Sales de la tienda."))
            break

# 修改：行动详情 挪到了 更新行动详情() 里面（在 更新技能() 上面），升级以后说明会跟着变
显示详情 = False

# 修改：删掉了 神器详情；背包、设置 现在都能用了
背包详情 = "看看身上的护符、天赋，喝消耗品（喝药水算一个回合）"
设置详情 = "退出这个存档（回到选择存档，可以玩别的存档）、换语言"          # 修改（语言）：设置里多了 换语言
背包详情_西班牙语 = "Mira tus amuletos y talentos, y bébete consumibles (beber una poción cuenta como un turno)"     # 新加（语言）
设置详情_西班牙语 = "Salir de este archivo (volver a elegir archivo para jugar otro) y cambiar el idioma"

def 更新可选行动():
    # 新加：现在能选哪些行动（原来写在 选择行动() 里面）。每次都从 全部行动 里重新挑一遍
    # 修改：原来判断的是 能量上限 == 100（永远成立，大招一直显示），现在能量满了才显示大招
    # 新加：前线装甲 蓄力的时候只能用 技能1、技能2（还能看背包、详情、设置），不能普攻、放大招
    global 可选行动
    可选行动 = []
    for 行动 in 全部行动:
        if 行动 == "[1] 普攻":
            if not 前线装甲蓄力中():
                可选行动.append(行动)
        elif 行动 == "[4] 大招":
            if 当前能量 == 能量上限 and not 前线装甲蓄力中():
                可选行动.append(行动)
        elif 行动 != "[5] __" and 行动 != "[7] __" and 行动 != "[8] __":
            可选行动.append(行动)

def 选择行动():
    # 修改：删掉了 神器 的那几行（以前有神器的时候会把 [5] 加进来）
    # 修改：算哪些行动能选的部分挪到了 更新可选行动() 里面（状态栏() 也要先算好）
    # 修改（语言）：显示的时候换成现在的语言（可选行动 里还是中文的，不用动）
    更新可选行动()
    显示的行动 = []
    for 行动 in 可选行动:
        显示的行动.append(行动文字(行动))
    print(" ".join(显示的行动))      # 修改：原来的 f"{" ".join(可选行动)}" 在 Python 3.11 及以下会报错

def 状态条刷新():
    # 修改：删掉了生命值的 ///// 条（生命值一多，条就很长），现在只做能量条；生命值在 状态栏() 里直接显示数字
    global 能量条_2, 敌人_能量条_2, 当前能量, 能量上限, 当前生命值, 最大生命值, 敌人_当前能量, 敌人_能量上限, 敌人_当前生命值, 敌人_最大生命值
    当前能量 = min(max(0, 当前能量), 能量上限)
    当前生命值 = min(max(0, 当前生命值), 生命值上限())      # 修改：最大生命值 → 生命值上限()（要算上护符加的生命值）
    敌人_当前能量 = min(max(0, 敌人_当前能量), 敌人_能量上限)
    敌人_当前生命值 = min(max(0, 敌人_当前生命值), 敌人_最大生命值)

    能量条_1 = int(能量上限 // 10)
    敌人_能量条_1 = int(敌人_能量上限 // 10)

    能量条_2 = ["_"] * 能量条_1
    敌人_能量条_2 = ["_"] * 敌人_能量条_1

    能量条填几个 = min(int(当前能量 // 10), len(能量条_2))
    敌人_能量条填几个 = min(int(敌人_当前能量 // 10), len(敌人_能量条_2))

    # 修改：i 改成中文的 第几格
    for 第几格 in range(能量条填几个):
        能量条_2[第几格] = "/"
    for 第几格 in range(敌人_能量条填几个):
        敌人_能量条_2[第几格] = "/"

def 刷新敌人(数值提升 = 0, 种类 = "普怪", 一定输 = False):
    # 修改：加了 数值提升（%）：普通敌人 0，精英怪 25~50，头目 50~100
    # 修改：加了 种类（"普怪" / "精英怪" / "头目" / "终章头目"）：按种类抽4个技能（看 抽取敌人技能()）；一定输 的头目不会抽到自爆
    global 敌人_最大生命值, 敌人_基础攻击力, 敌人_基础防御力, 敌人_基础命中率, 敌人_基础暴击率, 敌人_基础暴击伤害, 敌人_当前生命值, 敌人_当前攻击力, 敌人_当前防御力, 敌人_当前命中率, 敌人_当前暴击率,  敌人_当前暴击伤害, 敌人_当前能量, 敌人_能量上限, 敌人_智能等级
    global 敌人种类, 敌人技能, 敌人_当前护盾, 敌人_嗜血剩余回合
    # 修改：原来是 * (层数/10)，第1层只剩10%的数值；现在是每层 +10%（第0层 = 原来的数值，第10层 = 两倍）
    # 修改：新的数值（你给的）：生命值、攻击力、防御力 每层 +12.5%（层数/8），命中、暴击 还是每层 +10%
    敌人_最大生命值 = random.randint(50, 100) * (1 + 层数/8)
    敌人_基础攻击力 = random.randint(40, 60) * (1 + 层数/8)
    敌人_基础防御力 = random.randint(30, 50) * (1 + 层数/8)
    敌人_基础命中率 = random.randint(70, 80) * (1 + 层数/10)
    敌人_基础暴击率 = random.randint(5, 10) * (1 + 层数/10)
    敌人_基础暴击伤害 = random.randint(150, 200) * (1 + 层数/10)

    # 新加：精英怪、头目的数值提升，只提升 生命值、攻击力、防御力
    #       （命中、暴击也一起提升的话太夸张：暴击伤害翻倍，一下暴击能打3~4倍）
    提升倍率 = 1 + 数值提升 / 100
    敌人_最大生命值 = 敌人_最大生命值 * 提升倍率
    敌人_基础攻击力 = 敌人_基础攻击力 * 提升倍率
    敌人_基础防御力 = 敌人_基础防御力 * 提升倍率

    敌人_当前生命值 = 敌人_最大生命值
    敌人_当前攻击力 = 敌人_基础攻击力
    敌人_当前防御力 = 敌人_基础防御力
    敌人_当前命中率 = 敌人_基础命中率
    敌人_当前暴击率 = 敌人_基础暴击率
    敌人_当前暴击伤害 = 敌人_基础暴击伤害

    # 新加：每个新敌人从0能量开始，并按层数抽一个智能等级
    敌人_能量上限 = 100
    敌人_当前能量 = 0
    敌人_智能等级 = 抽取智能等级()

    # 新加：抽4个技能，护盾、嗜血从0开始
    敌人种类 = 种类
    敌人技能 = 抽取敌人技能(种类, 一定输)
    敌人_当前护盾 = 0
    敌人_嗜血剩余回合 = 0

def 状态栏():
    global 显示详情, 当前生命值, 当前能量, 当前攻击力, 当前防御力, 当前命中率, 当前暴击率, 当前暴击伤害, 当前持有金币, 可选行动, 行动详情, 背包详情, 设置详情, 敌人_当前生命值, 敌人_当前能量, 敌人_当前攻击力, 敌人_当前防御力, 敌人_当前命中率, 敌人_当前暴击率, 敌人_当前暴击伤害, 能量条_2, 敌人_能量条_2
    if 显示详情:
        # 修改：攻击力、防御力 显示战斗里真正用的数值（算上增益、技能、形态），生命值后面加上了上限
        # 修改：生命值 round → 生命值文字（还活着最少显示1，不会显示成0）。下面敌人的、没开详情的 也一样
        更新行动详情()          # 新加：技能说明直接显示伤害数字，攻击力每回合都会变，所以每次显示前重新生成
        更新可选行动()          # 新加：先算好现在能选哪些行动（原来要等 选择行动() 才算，满能量的回合 [4] 大招 的说明会晚一个回合才出现）
        玩家状态栏 = 文(f"""
[玩家]
    生命值:【{生命值文字(当前生命值)}/{round(生命值上限())}】|能量:【{round(当前能量)}】|攻击力:【{round(战斗攻击力())}】|防御力:【{round(战斗防御力())}】
    命中率:【{round(当前命中率)}】|暴击率:【{round(当前暴击率)}】|暴击伤害:【{round(当前暴击伤害)}】|金币数量:【{round(当前持有金币)}】""",
                        f"""
[Jugador]
    Vida:【{生命值文字(当前生命值)}/{round(生命值上限())}】|Energía:【{round(当前能量)}】|Ataque:【{round(战斗攻击力())}】|Defensa:【{round(战斗防御力())}】
    Precisión:【{round(当前命中率)}】|Prob. crítico:【{round(当前暴击率)}】|Daño crítico:【{round(当前暴击伤害)}】|Monedas:【{round(当前持有金币)}】""")
        if 战斗状态文字() != "":
            玩家状态栏 += 文(f"\n    状态: {战斗状态文字()}", f"\n    Estado: {战斗状态文字()}")            # 新加：增益、护盾、技能效果……

        if "[1] 普攻" in 可选行动:
            玩家状态栏 += 文(f"\n    [1] 普攻: {行动详情[0]}", f"\n    [1] Ataque básico: {行动详情[0]}")
        if "[2] 技能1" in 可选行动:
            玩家状态栏 += 文(f"\n    [2] 技能1: {行动详情[1]}", f"\n    [2] Habilidad 1: {行动详情[1]}")
        if "[3] 技能2" in 可选行动:
            玩家状态栏 += 文(f"\n    [3] 技能2: {行动详情[2]}", f"\n    [3] Habilidad 2: {行动详情[2]}")
        if "[4] 大招" in 可选行动:
            玩家状态栏 += 文(f"\n    [4] 大招: {行动详情[3]}", f"\n    [4] Definitiva: {行动详情[3]}")

        if 被动1解锁:          # 修改：原来是 if 被动1:（被动1 一直是 False，解锁了也显示不出来）
            玩家状态栏 += 文(f"\n    被动1: {行动详情[4]}", f"\n    Pasiva 1: {行动详情[4]}")
        if 被动2解锁:
            玩家状态栏 += 文(f"\n    被动2: {行动详情[5]}", f"\n    Pasiva 2: {行动详情[5]}")
        if 准进阶被动解锁 and 有准进阶被动():         # 修改：被动3 → 准进阶被动（转职以后叫 进阶被动）
            if 行动详情_角色 in 进阶职业:
                玩家状态栏 += 文(f"\n    进阶被动: {行动详情[6]}", f"\n    Pasiva avanzada: {行动详情[6]}")
            else:
                玩家状态栏 += 文(f"\n    准进阶被动: {行动详情[6]}", f"\n    Pasiva pre-avanzada: {行动详情[6]}")
        if len(当前持有天赋的列表) > 0:          # 新加（第三步）：身上的天赋
            玩家状态栏 += 文(f"\n    天赋: {'、'.join(当前持有天赋的列表)}",
                             f"\n    Talentos: {名单(当前持有天赋的列表)}")

        # 修改：删掉了 [5] 神器
        玩家状态栏 += 文(f"\n    [6] 背包: {背包详情}", f"\n    [6] Mochila: {背包详情_西班牙语}")
        玩家状态栏 += 文(f"\n    [0] 设置: {设置详情}", f"\n    [0] Ajustes: {设置详情_西班牙语}")

        print(玩家状态栏)

        # 修改：攻击力显示战斗里真正用的（算上嗜血）；多了 状态（护盾、嗜血）；下面4个技能换成这个怪抽到的技能（看 敌人技能说明()）
        敌人状态栏 = 文(f"""
[{敌人名字}]
    生命值:【{生命值文字(敌人_当前生命值)}/{round(敌人_最大生命值)}】|能量:【{round(敌人_当前能量)}】|攻击力:【{round(敌人战斗攻击力())}】|防御力:【{round(敌人_当前防御力)}】
    命中率:【{round(敌人_当前命中率)}】|暴击率:【{round(敌人_当前暴击率)}】|暴击伤害:【{round(敌人_当前暴击伤害)}】|智能等级:【{敌人_智能等级}】""",
                        f"""
[{敌人名字文字()}]
    Vida:【{生命值文字(敌人_当前生命值)}/{round(敌人_最大生命值)}】|Energía:【{round(敌人_当前能量)}】|Ataque:【{round(敌人战斗攻击力())}】|Defensa:【{round(敌人_当前防御力)}】
    Precisión:【{round(敌人_当前命中率)}】|Prob. crítico:【{round(敌人_当前暴击率)}】|Daño crítico:【{round(敌人_当前暴击伤害)}】|Nivel de IA:【{敌人_智能等级}】""")
        if 敌人状态文字() != "":
            敌人状态栏 += 文(f"\n    状态: {敌人状态文字()}", f"\n    Estado: {敌人状态文字()}")
        for 技能 in 敌人技能:
            敌人状态栏 += 文(f"\n    {技能}: {敌人技能说明(技能)}", f"\n    {名(技能)}: {敌人技能说明(技能)}")
        print(敌人状态栏 + "\n")

    else:
        状态条刷新()
        # 修改：里面的引号改成单引号，Python 3.11 及以下也能运行
        # 修改：HP 不画 ///// 条了，直接显示数字（现在/上限）；SP 还是条。敌人显示名字（看 敌人名字）
        print(文(f"[玩家]: HP【{生命值文字(当前生命值)}/{round(生命值上限())}】 SP【{''.join(能量条_2)}】",
                 f"[Jugador]: HP【{生命值文字(当前生命值)}/{round(生命值上限())}】 SP【{''.join(能量条_2)}】"))
        if 战斗状态文字() != "":
            print(文(f"        状态: {战斗状态文字()}", f"        Estado: {战斗状态文字()}"))              # 新加：没开详情也能看到增益、护盾、技能效果
        print(文(f"[{敌人名字}]: HP【{生命值文字(敌人_当前生命值)}/{round(敌人_最大生命值)}】 SP【{''.join(敌人_能量条_2)}】",
                 f"[{敌人名字文字()}]: HP【{生命值文字(敌人_当前生命值)}/{round(敌人_最大生命值)}】 SP【{''.join(敌人_能量条_2)}】"))
        if 敌人状态文字() != "":
            print(文(f"        状态: {敌人状态文字()}", f"        Estado: {敌人状态文字()}"))              # 新加：敌人的护盾、嗜血

def 有没有暴击(暴击率, 暴击伤害):
    # 修改：randint(0,100) 改成 (1,100)。原来抽到0时 0 <= 0 成立，暴击率0%也有约1%会暴击
    if random.randint(1,100) <= 暴击率:
        print(文("暴击！", "¡Crítico!"))
        return 暴击伤害 / 100        # 修改：暴击伤害200 → ×2.0（原来直接返回200，伤害会×200）
    else:
        return 1

def 有没有命中(命中率):
    if random.randint(1,100) <= 命中率:      # 修改：同上，0 改成 1
        return 1
    else:
        return 0

def 防御减伤倍率(防御力):
    # 新加：防御后还剩多少伤害（防御45 → 剩 1 - 45/195 ≈ 77%）
    # 原来写在 伤害计算公式() 里面，敌人智能估算伤害也要用，所以单独拿出来
    return 1 - (防御力 / (防御力 + 150))

def 伤害计算公式(伤害, 防御力, 命中率, 暴击率, 暴击伤害):
    # 修改：先判定命中，没打中直接返回0（不然没打中也可能显示"暴击！"）
    # 暴击率传0 = 这一招不能暴击
    if 有没有命中(命中率) == 0:
        return 0
    造成的伤害 = 伤害 * 有没有暴击(暴击率, 暴击伤害) * 防御减伤倍率(防御力)
    return 造成的伤害

