def 七魄数量():
    # 身上有几个七魄（第九章要7个都有）
    数量 = 0
    for 名字 in 七魄:
        if 有天赋(名字):
            数量 += 1
    return 数量

def 七魄齐全():
    return 七魄数量() == len(七魄)

def 成神的道路总数():
    # 成神的道路一共有几个（七魄 + 三魂 = 10）
    return 天赋种类列表.count("成神的道路")

def 当前路线():
    # 看身上的天赋走哪条路线：某一种 ≥5个，而且比另外两种都多 → "天使" / "恶魔" / "成神"；都不是 → "没达成"
    天使 = 天赋数量("天使的馈赠")
    恶魔 = 天赋数量("恶魔的低语")
    成神 = 天赋数量("成神的道路")
    if 天使 >= 路线最少天赋 and 天使 > 恶魔 and 天使 > 成神:
        return "天使"
    if 恶魔 >= 路线最少天赋 and 恶魔 > 天使 and 恶魔 > 成神:
        return "恶魔"
    if 成神 >= 路线最少天赋 and 成神 > 天使 and 成神 > 恶魔:
        return "成神"
    return "没达成"

def 路线文字(路线):
    # 显示用："天使" → "【天使路线】"，"没达成" → "【哪条路线都没走成】"
    if 路线 == "没达成":
        return 文("【哪条路线都没走成】", "【No sigues ninguna ruta】")
    return 文(f"【{路线}路线】", f"【Ruta: {名(路线)}】")

def 路线位置(章节, 路线):
    # 这一章的这条路线在 路线_X 的第几行（找不到 = -1）
    for 编号 in range(len(路线_章节)):
        if 路线_章节[编号] == 章节 and 路线_路线[编号] == 路线:
            return 编号
    return -1

def 最终头目一定输(路线):
    # 这一章的最终头目是不是一定输（剧情杀）
    if 当前章节 in 路线_章节:
        return 路线_一定输[路线位置(当前章节, 路线)]
    if 当前章节 in 七魄才能赢的章节:
        return not 七魄齐全()
    if 当前章节 in 十成神才能赢的章节:
        return 天赋数量("成神的道路") < 成神的道路总数()
    return False

def 一定输提示():
    # 被剧情杀以后告诉玩家差什么（第九章：七魄；第八章：10个成神的道路）
    if 当前章节 in 七魄才能赢的章节:
        print(文(f">> 提示：七魄要全部都有才打得赢（现在 {七魄数量()}/{len(七魄)}）",
                 f">> Pista: necesitas las 7 Emociones para poder ganar (ahora tienes {七魄数量()}/{len(七魄)})"))
    elif 当前章节 in 十成神才能赢的章节:
        print(文(f">> 提示：成神的道路要全部都有才打得赢（现在 {天赋数量('成神的道路')}/{成神的道路总数()}）",
                 f">> Pista: necesitas todo el Camino a la Divinidad para poder ganar (ahora tienes {天赋数量('成神的道路')}/{成神的道路总数()})"))

def 输了也继续():
    # 这一章打输最终头目也不算死（剧情照样往下走）：有 章节输了文字 或者 章节输了结局 的章节
    位置 = 章节列表.index(当前章节)
    return 章节输了文字[位置] != "" or 章节输了结局[位置] != ""

def 这一章的结局(打赢了, 路线):
    # 最终头目打完以后看到哪个结局（"" = 没有结局）。第四、五、六章看 路线_结局，其他章节看 章节赢了结局 / 章节输了结局
    if 当前章节 in 路线_章节:
        return 路线_结局[路线位置(当前章节, 路线)]
    位置 = 章节列表.index(当前章节)
    if 打赢了:
        return 章节赢了结局[位置]
    return 章节输了结局[位置]

def 看到结局(结局):
    # 放结局（标题 + 文字），记进 已看过的结局（永久进度，存在 进度N.txt 里）
    位置 = 结局名字列表.index(结局)
    print(文(f"\n★ {结局}「{结局标题列表[位置]}」 ★", f"\n★ {名(结局)} «{结局标题列表_西班牙语[位置]}» ★"))
    print(文(结局文字列表[位置], 结局文字列表_西班牙语[位置]))          # 修改（语言）
    if 结局 not in 已看过的结局:
        已看过的结局.append(结局)
        if 结局 == 半个结局:
            print(文(">> ……这好像还不是全部。", ">> ...Parece que esto no es todo."))
        else:
            print(文(f">> 第一次看到这个结局！（已经看过 {结局数量(已看过的结局)}/{len(结局名字列表) - 1} 个结局）",
                     f">> ¡Primera vez que ves este final! (Llevas {结局数量(已看过的结局)}/{len(结局名字列表) - 1} finales vistos)"))

def 结局数量(结局们):
    # 看过几个结局（结局10（前一半） 不算：它只是结局10的一半）
    数量 = 0
    for 结局 in 结局们:
        if 结局 != 半个结局:
            数量 += 1
    return 数量

# ==================================================================
#                             快照头目（第五步）
# ==================================================================

# 新加：有几个头目是「以前的你」（看剧情大纲的「快照头目」）
#   到了下面的时间点，就把你那时候的数值记下来（= 快照），存进 进度N.txt（死了、换一局都不会没）
#   以后打到对应的头目，它的数值就换成快照里的：职业、生命值上限、攻击力、防御力、命中率、暴击率、暴击伤害（护符、天赋都算进去）
#   只存数值，不存技能：快照头目用的还是敌人的招式和智能
#   同一个快照存了好几次 → 用最新的；还没存过（例：测试模式直接跳过去玩）→ 跟普通头目一样
#   修改：存快照、打到快照头目的时候都不会提示（不然太明显，要玩家自己发现）。想看存了什么：开发者模式的 /快照
# 六个列表一一对应，一行 = 一个快照
快照_名字 = ["第六章的你", "第九章 阴的你", "第九章 阳的你", "第八章的你"]
快照_存的章节 = ["第六章", "第九章 阴", "第九章 阳", "第八章"]
快照_什么时候存 = ["打赢", "走到", "走到", "打赢"]       # 走到 = 走到最终头目就存（输赢都存）；打赢 = 打赢最终头目才存
快照_存的路线 = ["恶魔", "", "", ""]                    # 第六章要走恶魔路线打赢才存（= 拿到结局7）；"" = 不看路线
快照_用在章节 = ["第八章", "第九章 和", "第九章 和", "第七章"]
快照_用在层数 = [21, 9, 10, 10]                          # 游戏里的层数：第八章的第21层 = 显示的第0层；第九章 和 的第9、10层 = 第-9、-10层
快照头目提升 = 0                    # 快照头目的 生命值、攻击力、防御力 再多加多少%（0 = 跟以前的你一模一样；觉得太难就改成负数，例：-20）
快照项目 = ["职业", "生命值上限", "攻击力", "防御力", "命中率", "暴击率", "暴击伤害"]     # 一个快照里存了什么（按这个顺序）

# 永久进度（会存进 进度N.txt）：跟 快照_名字 一一对应
# 一个快照 = 一段文字，例："战士,250,180.5,60,90,25,300"（顺序看 快照项目）；"" = 还没存
已存的快照 = ["", "", "", ""]

def 现在的快照():
    # 把你现在的数值变成一段快照文字。攻击力、防御力 用 当前攻击力、当前防御力（护符、天赋都算进去了）
    # 有 色欲 的话，跟战斗里一样：防御力变0，攻击力 + 防御力÷2
    攻击力 = 当前攻击力
    防御力 = 当前防御力
    if 有天赋("色欲"):
        攻击力 += 防御力 / 2
        防御力 = 0
    数值们 = [生命值上限(), 攻击力, 防御力, 当前命中率, 当前暴击率, 当前暴击伤害]
    文字们 = [行动详情_角色]
    for 数值 in 数值们:
        文字们.append(数值文字(数值))
    return ",".join(文字们)

def 拆开快照(快照):
    # "战士,250,180.5,60,90,25,300" → "战士", [250, 180.5, 60, 90, 25, 300]（一次返回两个东西）
    拆开 = 快照.split(",")
    数值们 = []
    for 文字 in 拆开[1:]:
        数值们.append(转数字(文字.strip()))
    return 拆开[0].strip(), 数值们

def 快照没坏(快照):
    # 检查快照的格式对不对（读进度的时候用）。"" 也算对（= 还没存）
    if 快照 == "":
        return True
    拆开 = 快照.split(",")
    if len(拆开) != len(快照项目):
        return False
    if 拆开[0].strip() not in 职业 and 拆开[0].strip() not in 进阶职业:
        return False
    for 文字 in 拆开[1:]:
        try:
            转数字(文字.strip())
        except ValueError:
            return False
    return True

def 存这一章的快照(时机, 路线):
    # 看看现在要不要存快照（时机 = "走到" / "打赢"）。存了 → True（存进度要另外调用 保存进度()）
    存了 = False
    for 编号 in range(len(快照_名字)):
        if 快照_存的章节[编号] == 当前章节 and 快照_什么时候存[编号] == 时机 and 快照_存的路线[编号] == 路线:
            已存的快照[编号] = 现在的快照()                # 悄悄存，不提示
            存了 = True
    return 存了

def 本层快照编号():
    # 这一层的头目是不是「以前的你」：是，而且存过快照 → 它在 快照_X 里的位置；不是 / 还没存过 → -1
    for 编号 in range(len(快照_名字)):
        if 快照_用在章节[编号] == 当前章节 and 快照_用在层数[编号] == 层数 and 已存的快照[编号] != "":
            return 编号
    return -1

def 用快照当敌人(快照, 数值提升):
    # 把刚生成的敌人的数值换成快照里的（战斗事件() 里调用）。生命值、攻击力、防御力 再加 数值提升%（跟 刷新敌人() 一样）
    global 敌人_最大生命值, 敌人_基础攻击力, 敌人_基础防御力, 敌人_基础命中率, 敌人_基础暴击率, 敌人_基础暴击伤害
    global 敌人_当前生命值, 敌人_当前攻击力, 敌人_当前防御力, 敌人_当前命中率, 敌人_当前暴击率, 敌人_当前暴击伤害
    职业名, 数值们 = 拆开快照(快照)
    提升倍率 = 1 + 数值提升 / 100
    敌人_最大生命值 = 数值们[0] * 提升倍率
    敌人_基础攻击力 = 数值们[1] * 提升倍率
    敌人_基础防御力 = 数值们[2] * 提升倍率
    敌人_基础命中率 = 数值们[3]
    敌人_基础暴击率 = 数值们[4]
    敌人_基础暴击伤害 = 数值们[5]
    敌人_当前生命值 = 敌人_最大生命值
    敌人_当前攻击力 = 敌人_基础攻击力
    敌人_当前防御力 = 敌人_基础防御力
    敌人_当前命中率 = 敌人_基础命中率
    敌人_当前暴击率 = 敌人_基础暴击率
    敌人_当前暴击伤害 = 敌人_基础暴击伤害

def 提升文字(提升):
    # 显示用：头目出场的时候写它的数值提升了多少。0 → 不写（快照头目一般是0）
    if 提升 == 0:
        return ""
    return 文(f"（生命值、攻击力、防御力 {带正负号(提升)}%）", f" (vida, ataque y defensa {带正负号(提升)}%)")

