def 要不要去(去的说法, 不去的说法):
    # 新加：遇到中立事件、特殊事件的时候，先问玩家要不要去。返回 True = 要去，False = 不去
    print(f"[1] {去的说法}")
    print(f"[0] {不去的说法}")
    return 输入数字(文("请选择: ", "Elige: "), 0, 1) == 1

def 普通战斗():
    # 新加：第1,2,4,6,8关
    # 修改：怪物有名字了（这一章的小怪里随机一个，看 章节小怪）
    global 敌人名字
    敌人名字 = 随机小怪()
    print(文(f"前方出现了一只{敌人名字}！", f"¡Aparece {敌人名字文字()} delante de ti!"))
    if 战斗事件():
        获得金币(随机金币(普通战斗金币最少, 普通战斗金币最多))

# ---------------------------- 中立事件 ----------------------------

def 中立事件():
    # 新加：第3关，按权重随机遇到一种情况
    事件 = 中立事件列表[按权重抽取(中立事件权重)]
    if 事件 == "临时战斗":
        临时战斗()
    elif 事件 == "流浪商人":
        流浪商人()
    elif 事件 == "路人有困难":
        路人有困难()
    elif 事件 == "神秘商人":
        神秘商人()
    elif 事件 == "休息":
        休息()
    elif 事件 == "临时头目":
        临时头目()

# 修改：下面每个事件都会先问要不要去（要不要去()），选了不去就什么都不发生（没有奖励，也没有风险）

def 临时战斗():
    global 敌人名字
    敌人名字 = 随机小怪()                              # 修改：怪物有名字了
    print(文(f"路上突然冲出一只{敌人名字}！", f"¡De repente, {敌人名字文字()} te sale al paso en el camino!"))
    if not 要不要去(文("迎战", "Pelear"), 文("绕路避开", "Dar un rodeo para evitarlo")):
        print(文("你绕了一段远路，躲开了它。", "Das un buen rodeo y lo esquivas."))
        return
    if 战斗事件():
        if random.randint(1, 100) <= 临时战斗金币概率:
            获得金币(随机金币(临时战斗金币最少, 临时战斗金币最多))
        else:
            print(文(f"{敌人名字}身上什么都没找到……", f"No encuentras nada encima de {敌人名字文字()}..."))

def 流浪商人():
    # 修改：原来护符还没做。现在：花15~30G买一个随机护符（买了才知道是什么），品质按 护符品质权重_随机 抽
    print(文("你遇到了流浪商人！", "¡Te encuentras con un mercader ambulante!"))
    商人卖护符("随机")

def 神秘商人():
    # 修改：跟流浪商人一样，但是品质按 护符品质权重_高品质 抽（品质更高）
    print(文("你遇到了神秘商人！", "¡Te encuentras con un mercader misterioso!"))
    商人卖护符("高品质")

def 商人卖护符(护符来源):
    # 新加：流浪商人、神秘商人共用：随机一个价格 → 问要不要买 → 买了才抽护符（护符来源 跟 获得护符() 的一样）
    # 修改：不再先问 看看他卖什么，价格直接写在选项里；选了不买，就跟原来的 不理他 一样
    global 当前持有金币
    价格 = 天赋价格(random.randint(商人护符价格最少, 商人护符价格最多))      # 修改（第三步）：算上 暴食
    print(文(f"“嘿嘿，{价格}G，包里的护符随便摸一个，摸到什么算什么~”（当前持有金币: {当前持有金币}G）",
             f"«Jejeje, por {价格}G metes la mano en la bolsa y te quedas el amuleto que saques, lo que te toque~» (Monedas: {当前持有金币}G)"))
    if 当前持有护符的数量 >= 最大持有护符的数量:
        print(文(">> 提醒：你的护符已经满了，买到以后要扔掉一个（或者不要新的，钱不退）",
                 ">> Ojo: ya llevas el máximo de amuletos, si compras uno tendrás que tirar otro (o no quedarte el nuevo, y el dinero no se devuelve)"))
    if not 要不要去(文(f"花{价格}G买一个",
                       f"Pagar {价格}G por uno"), 文("不理他，继续赶路", "Pasar de él y seguir tu camino")):
        print(文("你没理他，继续赶路。", "Pasas de él y sigues tu camino."))
        return
    if 当前持有金币 < 价格:
        print(文(">> 金币不足!商人白了你一眼。", ">> ¡No tienes suficientes monedas! El mercader te mira mal."))
        return
    当前持有金币 -= 价格
    print(文(f">> 花了{价格}G。（当前持有金币: {当前持有金币}G）",
             f">> Pagas {价格}G. (Monedas: {当前持有金币}G)"))
    获得护符(护符来源)

def 路人有困难():
    global 当前持有金币
    print(文("路边有个人好像遇到了困难。", "Hay alguien al lado del camino que parece tener problemas."))
    if not 要不要去(文("上前帮他一把",
                       "Acercarte a echarle una mano"), 文("装作没看见", "Hacer como que no lo ves")):
        print(文("你装作没看见，继续赶路。", "Haces como que no lo ves y sigues tu camino."))
        return
    print(文("你上前帮了他一把。", "Te acercas y le echas una mano."))
    if random.randint(1, 100) <= 路人好人概率:
        print(文("他是个好人，非常感谢你！", "¡Es buena gente y te da las gracias un montón!"))
        if random.randint(1, 100) <= 好人给金币概率:
            获得金币(随机金币(好人金币最少, 好人金币最多))
        else:
            获得护符("随机")
    else:
        print(文("……他是个骗子！", "...¡Es un estafador!"))
        if random.randint(1, 100) <= 坏人骗钱概率 and 当前持有金币 > 0:
            骗走 = max(1, round(当前持有金币 * random.randint(坏人骗走最少, 坏人骗走最多) / 100))
            当前持有金币 -= 骗走
            print(文(f">> 你被骗走了{骗走}枚金币！（当前持有金币: {当前持有金币}G）",
                     f">> ¡Te ha timado {骗走} monedas! (Monedas: {当前持有金币}G)"))
        else:
            print(文("还好你反应快，什么都没损失。", "Menos mal que reaccionas rápido y no pierdes nada."))

def 休息():
    print(文("你找到了一个看起来很安全的地方。", "Encuentras un sitio que parece bastante seguro."))
    if not 要不要去(文("休息一会儿", "Descansar un rato"), 文("继续赶路", "Seguir tu camino")):
        print(文("你没有休息，继续赶路。", "No descansas y sigues tu camino."))
        return
    print(文("你休息了一会儿。", "Descansas un rato."))
    恢复生命值(random.choice(休息恢复比例))

def 临时头目():
    global 敌人名字
    提升 = random.randint(头目数值提升最少, 头目数值提升最多)
    敌人名字 = 随机头目()                              # 修改：临时头目也有名字了（这一章的头目里随机一个）
    print(文(f"一股可怕的气息……临时头目【{敌人名字}】挡住了你的去路！（生命值、攻击力、防御力 +{提升}%）",
             f"Sientes algo muy chungo... ¡El jefe sorpresa【{敌人名字文字()}】te corta el paso! (vida, ataque y defensa +{提升}%)"))
    if not 要不要去(文("挑战它", "Enfrentarte a él"), 文("绕路避开", "Dar un rodeo para evitarlo")):
        print(文("你屏住呼吸，悄悄绕开了它。", "Aguantas la respiración y lo rodeas sin hacer ruido."))
        return
    if 战斗事件(提升, 种类="头目"):              # 修改：临时头目按头目的概率抽技能
        获得护符("高品质")

