def 特殊事件():
    # 新加：第7关，按权重随机遇到一种情况
    事件 = 特殊事件列表[按权重抽取(特殊事件权重)]
    if 事件 == "赌场":
        赌场()
    elif 事件 == "修炼场":
        修炼场()
    elif 事件 == "锻造店":
        锻造店()
    elif 事件 == "精英怪":
        精英怪()
    elif 事件 == "温泉":
        温泉()

def 赌场():
    # 每次来只能赌一次。本来就可以选 [0] 离开（= 不赌），所以不用再问 要不要去()
    global 当前持有金币
    print(文("你走进了一家赌场，里面闹哄哄的。", "Entras en un casino, dentro hay un jaleo tremendo."))
    if 当前持有金币 < min(赌场下注金额):
        print(文(f"……但你只有{当前持有金币}G，连最小的赌注都不够，被门口的保安请了出去。",
                 f"...Pero solo tienes {当前持有金币}G, no te llega ni para la apuesta más pequeña, y el segurata de la puerta te echa."))
        return
    print(文(f"当前持有金币: [{当前持有金币}G]", f"Monedas: [{当前持有金币}G]"))
    for 编号 in range(len(赌场下注金额)):
        print(文(f"[{编号 + 1}] 下注{赌场下注金额[编号]}G，{赌场胜率[编号]}%概率赢{赌场赔率}倍",
                 f"[{编号 + 1}] Apostar {赌场下注金额[编号]}G, {赌场胜率[编号]}% de probabilidad de ganar x{赌场赔率}"))
    print(文("[0] 离开", "[0] Irte"))
    while True:
        选择 = 输入数字(文("请选择: ", "Elige: "), 0, len(赌场下注金额))
        if 选择 == 0:
            print(文("你离开了赌场。", "Te vas del casino."))
            return
        下注 = 赌场下注金额[选择 - 1]
        if 当前持有金币 >= 下注:
            break
        print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))                           # 钱不够就重新选（选便宜的，或者离开）
    当前持有金币 -= 下注
    if random.randint(1, 100) <= 赌场胜率[选择 - 1]:
        奖金 = 下注 * 赌场赔率                          # 赌场的奖金是固定的，不算 额外获得金币加成
        当前持有金币 += 奖金
        print(文(f">> 赢了！拿回{奖金}G！（当前持有金币: {当前持有金币}G）",
                 f">> ¡Has ganado! ¡Te llevas {奖金}G! (Monedas: {当前持有金币}G)"))
    else:
        print(文(f">> 输了……{下注}G没了。（当前持有金币: {当前持有金币}G）",
                 f">> Has perdido... Adiós a tus {下注}G. (Monedas: {当前持有金币}G)"))

def 修炼场():
    global 普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级, 被动1解锁, 被动2解锁
    print(文("你来到了修炼场，师傅愿意免费教你一招（随机升级一个还没满级的技能或被动）。",
             "Llegas a un campo de entrenamiento y el maestro quiere enseñarte algo gratis (mejora al azar una habilidad o pasiva que no esté al máximo)."))
    # 修改：去掉了 被动3。准进阶被动只能在锻炼里解锁（转职也只能在锻炼里突破）
    技能名字 = ["普攻", "技能1", "技能2", "大招", "被动1", "被动2"]
    if len(还没满级的技能()) == 0:
        print(文("……但你的技能和被动全都满级了，师傅只能对你竖起大拇指。",
                 "...Pero ya tienes todas las habilidades y pasivas al máximo, así que el maestro solo puede ponerte un pulgar arriba."))
        return
    # 新加：可以不学（随机升级可能会打乱你想要的被动等级，比如转职的条件）
    if not 要不要去(文("跟师傅学",
                       "Aprender del maestro"), 文("谢过师傅，离开", "Dar las gracias al maestro e irte")):
        print(文("你谢过师傅，离开了修炼场。",
                 "Le das las gracias al maestro y te vas del campo de entrenamiento."))
        return
    能升级的技能 = 还没满级的技能()                    # 修改（控制台）：问完再看一次（开发者模式可能在控制台里把技能都升满了）
    if len(能升级的技能) == 0:
        print(文("……但你的技能和被动全都满级了，师傅只能对你竖起大拇指。",
                 "...Pero ya tienes todas las habilidades y pasivas al máximo, así que el maestro solo puede ponerte un pulgar arriba."))
        return

    编号 = random.choice(能升级的技能)                 # 随机挑一个没满级的
    if 编号 == 0:
        普攻等级 += 1
    elif 编号 == 1:
        技能1等级 += 1
    elif 编号 == 2:
        技能2等级 += 1
    elif 编号 == 3:
        大招等级 += 1
    elif 编号 == 4:
        被动1等级 += 1
        被动1解锁 = True                               # 被动从0升到1 = 解锁
    elif 编号 == 5:
        被动2等级 += 1
        被动2解锁 = True
    更新技能()

    新等级 = [普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级][编号]      # 升级以后的等级
    if 编号 >= 4 and 新等级 == 1:
        print(文(f">> {技能名字[编号]}已成功解锁!", f">> ¡{名(技能名字[编号])} desbloqueada!"))
    else:
        print(文(f">> {技能名字[编号]}成功升级到 lv {新等级}!", f">> ¡{名(技能名字[编号])} sube a lv {新等级}!"))

def 还没满级的技能():
    # 新加：还没满级（lv5）的技能、被动是哪几个（原来写在 修炼场() 里面）
    # 编号：0 普攻 / 1 技能1 / 2 技能2 / 3 大招 / 4 被动1 / 5 被动2
    技能等级列表 = [普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级]
    能升级的技能 = []
    for 编号 in range(len(技能等级列表)):
        if 技能等级列表[编号] < 5:                    # 只挑没满级的（lv5 的不会被随机到）
            能升级的技能.append(编号)
    return 能升级的技能

def 锻造店():
    # 修改：原来护符还没做。现在：花金币把护符升一个品质（平凡→罕见→稀有→史诗→传奇→唯一），有几率失败
    # 价格、失败率看 锻造花费、锻造失败率。可以一直升级，选 [0] 才离开
    global 当前持有金币
    print(文("你来到了一家锻造店！", "¡Llegas a una herrería!"))
    if not 要不要去(文("进去看看", "Entrar a echar un vistazo"), 文("离开", "Irte")):
        print(文("你离开了锻造店。", "Te vas de la herrería."))
        return
    最高品质 = len(护符品质列表) - 1                     # 唯一 在列表的最后一位
    while True:
        if 当前持有护符的数量 == 0:
            print(文("……但你身上一个护符都没有，铁匠让你下次再来。",
                     "...Pero no llevas ningún amuleto, así que el herrero te dice que vuelvas otro día."))
            return
        print(文(f"\n当前持有金币: [{当前持有金币}G]", f"\nMonedas: [{当前持有金币}G]"))
        print(文("选一个护符升级品质（失败了钱不退，护符不变）:",
                 "Elige un amuleto para subirle la calidad (si sale mal, no te devuelven el dinero y el amuleto se queda igual):"))
        for 编号 in range(当前持有护符的数量):
            护符 = 当前持有护符的列表[编号]
            品质位置, 种类位置 = 拆分护符(护符)
            if 品质位置 == 最高品质:
                print(文(f"[/] {护符说明(护符)}（已经是最高品质）",
                         f"[/] {护符说明(护符)} (ya tiene la calidad más alta)"))
            else:
                新护符 = f"{护符品质列表[品质位置 + 1]} {护符种类列表[种类位置]}"
                print(文(f"[{编号 + 1}] {护符说明(护符)} >>> {护符说明(新护符)} 花费[{锻造花费[品质位置 + 1]}G] 失败率{锻造失败率[品质位置 + 1]}%",
                         f"[{编号 + 1}] {护符说明(护符)} >>> {护符说明(新护符)} cuesta [{锻造花费[品质位置 + 1]}G] prob. de fallo {锻造失败率[品质位置 + 1]}%"))
        print(文("[0] 离开", "[0] Irte"))
        选择 = 输入数字(文("请选择: ", "Elige: "), 0, 当前持有护符的数量)
        if 选择 == 0:
            print(文("你离开了锻造店。", "Te vas de la herrería."))
            return
        if 选择 > 当前持有护符的数量:
            continue                                # 新加（控制台）：选的时候护符变少了（在控制台里扔掉了）→ 重新列一次
        护符 = 当前持有护符的列表[选择 - 1]
        品质位置, 种类位置 = 拆分护符(护符)
        if 品质位置 == 最高品质:
            print(文(">> 这个护符已经是最高品质了!", ">> ¡Este amuleto ya tiene la calidad más alta!"))
        elif 当前持有金币 < 锻造花费[品质位置 + 1]:
            print(文(">> 金币不足!", ">> ¡No tienes suficientes monedas!"))
        else:
            花费 = 锻造花费[品质位置 + 1]
            当前持有金币 -= 花费
            if random.randint(1, 100) <= 锻造失败率[品质位置 + 1]:
                print(文(f">> 锻造失败了……{花费}G没了，护符还是原来的样子。（当前持有金币: {当前持有金币}G）",
                         f">> La forja ha salido mal... Adiós a tus {花费}G y el amuleto se queda igual. (Monedas: {当前持有金币}G)"))
            else:
                新护符 = f"{护符品质列表[品质位置 + 1]} {护符种类列表[种类位置]}"
                换掉护符(选择 - 1, 新护符)
                print(文(f">> 锻造成功！【{护符说明(护符)}】>>> 【{护符说明(新护符)}】（当前持有金币: {当前持有金币}G）",
                         f">> ¡Forja completada!【{护符说明(护符)}】>>>【{护符说明(新护符)}】(Monedas: {当前持有金币}G)"))

def 精英怪():
    global 敌人名字
    提升 = random.randint(精英数值提升最少, 精英数值提升最多)
    敌人名字 = "精英" + 随机小怪()                     # 修改：精英怪也有名字了：「精英史莱姆」
    print(文(f"{敌人名字}出现了！（生命值、攻击力、防御力 +{提升}%）",
             f"¡Aparece {敌人名字文字()}! (vida, ataque y defensa +{提升}%)"))
    if not 要不要去(文("挑战", "Pelear"), 文("绕路避开", "Dar un rodeo para evitarlo")):
        print(文(f"你绕开了{敌人名字}。", f"Rodeas a {敌人名字文字()} y sigues."))
        return
    if 战斗事件(提升, 种类="精英怪"):            # 修改：按精英怪的概率抽技能
        奖励 = 按权重抽取(精英奖励权重)                # 0 金币 / 1 护符 / 2 没有奖励
        if 奖励 == 0:
            获得金币(随机金币(精英金币最少, 精英金币最多))
        elif 奖励 == 1:
            获得护符("随机")
        else:
            print(文(f"{敌人名字}身上什么都没有……白打了。",
                     f"{敌人名字文字()} no llevaba nada encima... Pelea para nada."))

def 温泉():
    print(文("你发现了一处温泉。", "Encuentras unas aguas termales."))
    if not 要不要去(文("泡一泡", "Darte un baño"), 文("不泡了，继续赶路", "Pasar del baño y seguir tu camino")):
        print(文("你没有泡温泉，继续赶路。", "No te bañas y sigues tu camino."))
        return
    print(文("泡完浑身舒服。", "Después del baño te sientes genial."))
    恢复生命值(温泉恢复比例)

# ---------------------------- 头目事件 ----------------------------

def 头目事件():
    # 新加：第9关（每层的头目一定要打，不能选不去）
    # 修改：头目有名字了；有台词的开打前说一句
    # 修改（第四步）：这一章最后一层的（最终头目）挪到了 最终头目事件() 里面
    #                 第九章 和 第-9层的陌生人：七魄没齐就一定输（剧情杀），这一局结束
    # 修改（第五步）：第九章 和 第-9层的陌生人 = 第九章 阴的你（快照头目：数值换成快照里的）
    global 敌人名字
    if 层数 >= 本章最后一层(当前章节):
        最终头目事件()
        return
    编号 = 本层快照编号()
    快照 = ""
    if 编号 != -1:
        提升 = 快照头目提升
        快照 = 已存的快照[编号]
    else:
        提升 = random.randint(头目数值提升最少, 头目数值提升最多)
    敌人名字 = 本层头目名字()
    print(文(f"第{显示层数(当前章节, 层数)}层的头目【{敌人名字}】出现了！{提升文字(提升)}",
             f"¡Aparece el jefe del piso {显示层数(当前章节, 层数)}:【{敌人名字文字()}】!{提升文字(提升)}"))
    if 本层头目台词() != "":
        print(本层头目台词())
    一定输 = 特别头目编号() != -1 and 当前章节 in 七魄才能赢的章节 and not 七魄齐全()
    if 战斗事件(提升, 0, 一定输, 快照, "头目"):        # 修改：按头目的概率抽技能
        打赢头目()
    elif 一定输 and not 要退出存档:
        七魄没齐结束()

def 打赢头目():
    # 新加：打赢头目以后：奖励 + 生命值回满（原来写在 头目事件() 里面，最终头目事件() 也要用）
    global 当前生命值
    print(文(f"你打败了【{敌人名字}】！", f"¡Has derrotado a【{敌人名字文字()}】!"))
    头目奖励()                                     # 修改：奖励挪到了 头目奖励() 里（第九章 和 的陌生人给天赋），在 天赋 那一部分
    当前生命值 = 生命值上限()                       # 新加：打完每一层的头目，生命值回满
    print(文(f">> 打完头目，生命值回满了！（生命值: {生命值文字(当前生命值)}/{round(生命值上限())}）",
             f">> ¡Después de ganar al jefe, se te llena la vida! (Vida: {生命值文字(当前生命值)}/{round(生命值上限())})"))

def 最终头目事件():
    # 新加（第四步）：这一章最后一层的第9关（看剧情大纲的「路线判定」「剧情杀」）
    #   第四、五、六章先看路线 → 决定打谁、能不能赢；第九章要七魄齐全、第八章要10个成神 才能赢，不然一定输
    #   数值：头目的提升 + 章节最终头目额外提升（第三章的魔神 +200%）；智能等级固定5
    #   打完以后：打赢了 → 章节打完()；输了 → 看是 剧情（不算死）还是 普通的死
    # 修改（第五步）：第九章 阴/阳：走到这里就存快照；第六章（结局7）、第八章：打赢了才存快照（看 快照_X）
    #                 第八章的魔神、第九章 和 第-10层的陌生人、第七章的人类 = 以前的你（快照头目）
    global 敌人名字, 这一局怎么结束
    位置 = 章节列表.index(当前章节)
    路线 = ""
    if 当前章节 in 路线_章节:
        路线 = 当前路线()
        print(文(f"你的天赋：{天赋路线文字()} → {路线文字(路线)}",
                 f"Tus talentos: {天赋路线文字()} → {路线文字(路线)}"))
    if 存这一章的快照("走到", 路线):
        保存进度(当前存档编号)                 # 走到就存：马上存进度（后面死了也不会没）
    编号 = 本层快照编号()
    快照 = ""
    if 编号 != -1:
        提升 = 快照头目提升
        快照 = 已存的快照[编号]
    else:
        提升 = random.randint(头目数值提升最少, 头目数值提升最多) + 章节最终头目额外提升[位置]
    敌人名字 = 本层头目名字()
    print(文(f"最终头目【{敌人名字}】出现了！{提升文字(提升)}",
             f"¡Aparece el jefe final【{敌人名字文字()}】!{提升文字(提升)}"))
    if 本层头目台词() != "":
        print(本层头目台词())
    一定输 = 最终头目一定输(路线)
    打赢了 = 战斗事件(提升, 最终头目智能等级, 一定输, 快照, "终章头目")       # 修改：按终章头目的概率抽技能
    if 要退出存档:
        return
    if 打赢了:
        存这一章的快照("打赢", 路线)             # 打赢才存的快照（章节打完() 会存进度）
        if 当前章节 == "第九章 和":
            打赢头目()                           # 第九章 和 打完还要接着打第八章：跟普通头目一样给奖励（地魂）、回满血
        else:
            print(文(f"你打败了【{敌人名字}】！", f"¡Has derrotado a【{敌人名字文字()}】!"))       # 其他章节这一局马上结束，不用给护符、回血了
        章节打完(True, 路线)
    elif 一定输 and 路线 == "没达成":
        print(文(f"{敌人名字}一挥手，你就倒下了。「力量这么杂，你到底想成为什么？」",
                 f"{敌人名字文字()} mueve la mano y caes al suelo. «Con un poder tan mezclado... ¿qué es lo que quieres ser?»"))
        这一局怎么结束 = "剧情杀"                 # 没有结局，这一章也不算打完
    elif 一定输 and 当前章节 == "第九章 和":
        七魄没齐结束()
    elif 一定输 or 输了也继续():
        if 一定输:
            一定输提示()                         # 第九章 阴/阳（七魄）、第八章（10个成神）：告诉玩家差什么
        章节打完(False, 路线)                    # 被剧情杀（第四章成神、第六章天使/成神……）或者 输了也继续的章节：剧情照样往下走
    # 剩下的：正常打输了 = 普通的死（打这一局() 会处理）

def 七魄没齐结束():
    # 新加（第四步）：第九章 和 的陌生人（第-9层、第-10层）：七魄没齐，一定输 → 这一局结束（不算死，也不算打完）
    global 这一局怎么结束
    print(文(f"{敌人名字}：「看来你还不是那个希望……」",
             f"{敌人名字文字()}: «Parece que todavía no eres esa esperanza...»"))
    一定输提示()
    这一局怎么结束 = "剧情杀"

# 修改：祝福事件() 做好了，挪到了 天赋 那一部分

def 关卡事件():
    # 修改：原来只是给 事件 赋了一个文字，什么都没发生；现在会真的调用每个事件
    # 修改：前面加上了现在是哪一章；层数用 显示层数()（第九章往下走，层数是负的）
    print(文(f"\n========== {当前章节} 第{显示层数(当前章节, 层数)}层 第{关卡}关 ==========",
             f"\n========== {名(当前章节)} · Piso {显示层数(当前章节, 层数)} · Sala {关卡} =========="))
    # 修改：最大生命值 → 生命值上限()，再加上护符数量。修改（第三步）：再加上天赋数量
    print(文(f"生命值:【{生命值文字(当前生命值)}/{round(生命值上限())}】|金币:【{当前持有金币}G】|护符:【{当前持有护符的数量}/{最大持有护符的数量}】|天赋:【{len(当前持有天赋的列表)}】",
             f"Vida:【{生命值文字(当前生命值)}/{round(生命值上限())}】|Monedas:【{当前持有金币}G】|Amuletos:【{当前持有护符的数量}/{最大持有护符的数量}】|Talentos:【{len(当前持有天赋的列表)}】"))
    剧情插话()                  # 新加：有的关卡开始前会插一段剧情（例：第二章第5层的那封信）
    if 关卡 == 3:
        中立事件()
    elif 关卡 == 5:
        商店()                  # 修改：商店现在能买药水（购买物品）、护符了
    elif 关卡 == 7:
        特殊事件()
    elif 关卡 == 9:
        头目事件()
    elif 关卡 == 10:
        祝福事件()
    else:
        普通战斗()              # 1,2,4,6,8

