def 章节全名(章节):
    # "第一章" → "第一章「讨伐魔王」"
    return 文(f"{章节}「{章节标题列表[章节列表.index(章节)]}」",
              f"{名(章节)} «{章节标题列表_西班牙语[章节列表.index(章节)]}»")

def 章节已解锁(章节):
    return 测试_解锁全部章节 or 章节 in 已解锁的章节

def 本章第一层(章节):
    # 新加：这一章从第几层开始（游戏里的层数）
    # 第八章接着第九章 和 打（同一局）：第九章 和 是第0~10层，第八章就从第11层开始，敌人数值也按11~21层算
    if 章节 == "第八章":
        return 最后一层 + 1
    return 第一层

def 本章最后一层(章节):
    # 新加：这一章打到第几层结束（游戏里的层数）。第八章是第21层
    if 章节 == "第八章":
        return 最后一层 * 2 + 1
    return 最后一层

def 显示层数(章节, 第几层):
    # 新加：游戏里的层数（一直是 0、1、2…… 往上加，敌人数值、金币都按它算）→ 显示给玩家看的层数
    # 第九章 阴/阳/和：往下走，0 → -10；第八章：从魔界最底下往上爬，第11~21层 显示成 -10 → 0；其他章节不变
    if 章节 in 往下走的章节:
        return -第几层
    if 章节 == "第八章":
        return 第几层 - 本章最后一层("第八章")
    return 第几层

def 游戏层数(章节, 显示的层):
    # 新加（控制台）：显示层数() 反过来：屏幕上显示的层数 → 游戏里的层数（例：第九章 的 -9 → 9；第八章 的 0 → 21）
    if 章节 in 往下走的章节:
        return -显示的层
    if 章节 == "第八章":
        return 显示的层 + 本章最后一层("第八章")
    return 显示的层

def 随机小怪():
    # 新加：这一章的小怪里随机挑一个名字
    return random.choice(章节小怪[章节列表.index(当前章节)])

def 随机头目():
    # 新加：这一章的头目里随机挑一个名字（临时头目用）
    return random.choice(章节头目[章节列表.index(当前章节)])

def 特别头目编号():
    # 新加：这一层有没有特别安排的头目（例：第九章 和 第-9层的陌生人）。有 → 它在 特别头目_X 里的位置，没有 → -1
    for 编号 in range(len(特别头目_章节)):
        if 特别头目_章节[编号] == 当前章节 and 特别头目_层数[编号] == 层数:
            return 编号
    return -1

def 本层头目名字():
    # 新加：这一层的头目叫什么：最后一层 → 最终头目；有特别安排的 → 特别头目；其他的按层数轮流用 章节头目
    # 修改（第四步）：第四、五、六章的最终头目看路线（看 路线_头目）
    位置 = 章节列表.index(当前章节)
    if 层数 >= 本章最后一层(当前章节):
        if 当前章节 in 路线_章节:
            return 路线_头目[路线位置(当前章节, 当前路线())]
        return 章节最终头目[位置]
    if 特别头目编号() != -1:
        return 特别头目_名字[特别头目编号()]
    名字们 = 章节头目[位置]
    return 名字们[(层数 - 本章第一层(当前章节)) % len(名字们)]       # % = 除完剩下的：用完了从头再来

def 本层头目台词():
    # 新加：这一层的头目开打前说什么（"" = 不说话）
    # 修改（第四步）：第四、五、六章的最终头目看路线（看 路线_台词）
    # 修改（语言）：按现在的语言，从中文的列表或者 _西班牙语 的列表里拿（两个列表一一对应）
    if 层数 >= 本章最后一层(当前章节):
        if 当前章节 in 路线_章节:
            位置 = 路线位置(当前章节, 当前路线())
            return 文(路线_台词[位置], 路线_台词_西班牙语[位置])
        位置 = 章节列表.index(当前章节)
        return 文(章节最终头目台词[位置], 章节最终头目台词_西班牙语[位置])
    if 特别头目编号() != -1:
        return 文(特别头目_台词[特别头目编号()], 特别头目_台词_西班牙语[特别头目编号()])
    return ""

def 剧情插话():
    # 新加：关卡开始的时候，看看有没有要插的剧情（看 插话_X）
    for 编号 in range(len(插话_章节)):
        if 插话_章节[编号] == 当前章节 and 插话_层数[编号] == 层数 and 插话_关卡[编号] == 关卡:
            print(文(f"\n{插话_内容[编号]}\n", f"\n{插话_内容_西班牙语[编号]}\n"))

def 开场白():
    # 新加：这一章开始的时候：标题 + 开场白
    print(f"\n========== {章节全名(当前章节)} ==========")
    位置 = 章节列表.index(当前章节)
    print(文(章节开场[位置], 章节开场_西班牙语[位置]))          # 修改（语言）

def 进入第八章():
    # 新加：第九章 和 的第-10层打完 → 被吸进空间裂缝 → 同一局接着打第八章（护符、天赋、等级、金币全部带过去）
    #       层数接着往上加（第11层开始，显示成第-10层），敌人也接着变强
    global 当前章节, 层数, 关卡
    当前章节 = "第八章"
    层数 = 本章第一层("第八章")
    关卡 = 0
    开场白()

def 解锁章节(章节):
    # 还没解锁才解锁，顺便告诉玩家（已经解锁了就什么都不做）
    if 章节 not in 已解锁的章节:
        已解锁的章节.append(章节)
        print(文(f"★ 解锁了新章节：{章节全名(章节)}！ ★", f"★ ¡Nuevo capítulo desbloqueado: {章节全名(章节)}! ★"))

def 解锁职业(职业名):
    # 新加：永久解锁进阶职业（存进 进度N.txt，存进度要另外调用 保存进度()）。第一次显示「狂战士已解锁」，已经解锁了就什么都不说
    if 职业名 not in 已解锁的职业:
        已解锁的职业.append(职业名)
        print(文(f"\n★ {职业名}已解锁！ ★", f"\n★ ¡{名(职业名)} desbloqueado! ★"))

def 检查解锁():
    # 解锁条件都写在这里（看剧情大纲的「整体流程」）。打完一章、打开存档的时候调用
    # 只会解锁，不会把解锁了的锁回去
    if "第一章" in 已打完的章节:
        解锁章节("第二章")
    if "第二章" in 已打完的章节:
        解锁章节("第三章")
    if "第三章" in 已打完的章节:
        解锁章节("第四章")
    if "结局1" in 已看过的结局 and "结局2" in 已看过的结局 and "结局3" in 已看过的结局:
        解锁章节("第五章")
    # 第六章：第五章走成神路线打赢魔神的时候直接解锁（没有结局可以看，写在 章节打完() 里）
    if "结局7" in 已看过的结局:
        解锁章节("第九章 阴")
        解锁章节("第九章 阳")
    if "第九章 阴" in 已打完的章节 and "第九章 阳" in 已打完的章节:
        解锁章节("第九章 和")
    if "第九章 和" in 已打完的章节:
        解锁章节("第八章")
    if "结局9" in 已看过的结局:
        解锁章节("第七章")          # 修改（第四步）：原来是 第八章打完；现在第八章输了也算打完（结局10（前一半）），要打赢（结局9）才解锁

def 章节打完(打赢了, 路线):
    # 这一章的最终头目打完了：放结局（或者一段话）→ 记下来 → 看看能解锁什么 → 存进度
    # 修改：打完的时候说一段话（看 章节结束）
    # 修改（第三步）：有的章节打赢会解锁天赋；第一次打完第三章，祝福开始出现恶魔的低语、天使的馈赠
    # 修改（第四步）：最终头目事件() 调用。打赢了 → True；输了但剧情继续（被剧情杀、输了也继续的章节）→ False
    #   有结局 → 放结局；没有结局 → 打赢了放 章节结束，输了放 章节输了文字
    #   打赢了才解锁天赋（看 打赢解锁天赋_X）；第五章成神路线打赢 → 解锁第六章
    global 这一局怎么结束
    位置 = 章节列表.index(当前章节)
    if 打赢了:
        print(文(f"\n★★★ {章节全名(当前章节)} 打完了！ ★★★", f"\n★★★ ¡{章节全名(当前章节)} completado! ★★★"))
    else:
        print(文(f"\n★★★ {章节全名(当前章节)} 结束了…… ★★★", f"\n★★★ {章节全名(当前章节)} se ha terminado... ★★★"))
    结局 = 这一章的结局(打赢了, 路线)
    if 结局 != "":
        看到结局(结局)
    elif 打赢了 and 章节结束[位置] != "":
        print(文(章节结束[位置], 章节结束_西班牙语[位置]))              # 修改（语言）
    elif not 打赢了 and 章节输了文字[位置] != "":
        print(文(章节输了文字[位置], 章节输了文字_西班牙语[位置]))
    第一次打完 = 当前章节 not in 已打完的章节
    if 第一次打完:
        已打完的章节.append(当前章节)
    if 打赢了:
        for 编号 in range(len(打赢解锁天赋_章节)):
            if 打赢解锁天赋_章节[编号] == 当前章节 and 打赢解锁天赋_路线[编号] == 路线:
                解锁天赋(打赢解锁天赋_名字[编号])
        if 当前章节 == "第五章" and 路线 == "成神":
            解锁章节("第六章")
    if 当前章节 == 坦克解锁章节 and 第一次打完:
        print(文("★ 新职业解锁：坦克！以后开新游戏可以选了 ★",
                 "★ ¡Nueva clase desbloqueada: Tanque! Ya puedes elegirla al empezar una partida nueva ★"))      # 新加
    if 当前章节 == "第三章" and 第一次打完:
        print(文("★ 以后的祝福里会出现【恶魔的低语】和【天使的馈赠】了！ ★",
                 "★ ¡A partir de ahora en las bendiciones saldrán【Susurro del Demonio】y【Don del Ángel】! ★"))
    检查解锁()
    保存进度(当前存档编号)
    这一局怎么结束 = "打完了"

def 选择章节():
    # 选一个解锁了的章节 → 开始新的一局。返回 True = 开始了，False = 回到选择存档
    # 没解锁的章节显示 ？？？（不剧透）
    # 修改：按 章节显示顺序 排（第一章……第九章），原来是按 章节列表（玩的顺序：第九章在第八章、第七章前面）
    while True:
        print(文("\n========== 选择章节 ==========", "\n========== Elige capítulo =========="))
        if 测试_解锁全部章节:
            print(文("（测试模式：所有章节都能选）", "(Modo prueba: puedes elegir todos los capítulos)"))
        for 编号 in range(len(章节显示顺序)):
            章节 = 章节显示顺序[编号]
            打完过 = ""
            if 章节 in 已打完的章节:
                打完过 = 文("（打完过）", " (completado)")
            if not 章节已解锁(章节):
                print(文("[/] ？？？", "[/] ???"))
            elif 章节 == "第八章" and not 测试_解锁全部章节:
                print(文(f"[/] {章节全名(章节)}（从第九章 和 一直打过去）{打完过}",
                         f"[/] {章节全名(章节)} (se llega jugando desde el Capítulo 9 Armonía){打完过}"))      # 新加：第八章 跟 第九章 和 是同一局
            else:
                print(f"[{编号 + 1}] {章节全名(章节)}{打完过}")
        print(文("[0] 返回", "[0] Volver"))
        编号 = 输入数字(文("请选择: ", "Elige: "), 0, len(章节显示顺序))
        if 编号 == 0:
            return False
        选的章节 = 章节显示顺序[编号 - 1]
        if not 章节已解锁(选的章节):
            print(文(">> 这一章还没解锁!", ">> ¡Este capítulo todavía no está desbloqueado!"))
        elif 选的章节 == "第八章" and not 测试_解锁全部章节:
            print(文(">> 第八章跟第九章 和 是同一局，要从第九章 和 一直打过去!",
                     ">> ¡El Capítulo 8 va en la misma partida que el Capítulo 9 Armonía, tienes que llegar jugando desde ahí!"))
        else:
            新游戏(选的章节)
            return True

def 打这一局():
    # 一关一关打下去，直到 死了 / 这一章打完了 / 被剧情杀 / 在设置里退出存档（修改：原来直接写在最下面的主循环里）
    # 返回 "死了" / "打完了" / "剧情杀" / "退出存档"
    global 关卡, 层数, 这一局怎么结束
    这一局怎么结束 = ""
    while True:
        关卡 += 1
        关卡事件()

        if 要退出存档:
            # 在设置里退出了存档。这一关没打完，不存档（下次从这一关重新开始）
            print(文(f"\n>> 已退出存档{当前存档编号}。下次从{当前章节} 第{显示层数(当前章节, 层数)}层第{关卡}关重新开始。",
                     f"\n>> Has salido del archivo {当前存档编号}. La próxima vez vuelves a empezar desde {名(当前章节)}, piso {显示层数(当前章节, 层数)}, sala {关卡}."))
            return "退出存档"

        if 这一局怎么结束 == "剧情杀":
            # 新加（第四步）：一定输又没有结局（没达成、第九章 和 的陌生人）：这一局结束，不算死，这一章也不算打完
            print(文("\n这一局结束了……下次再来吧。", "\nEsta partida se ha acabado... ¡Vuelve otra vez!"))
            清空存档(当前存档编号)
            return "剧情杀"

        if 这一局怎么结束 == "打完了":
            # 修改（第四步）：原来是「最后一层的第9关打完」。现在 最终头目事件() 打完会设成 "打完了"（打赢了，或者输了但剧情继续）
            #                 章节打完()（结局、解锁、存进度）在 最终头目事件() 里已经调用过了。最后一层的第10关不给祝福
            if 当前章节 != "第九章 和":
                清空存档(当前存档编号)          # 这一局结束了，下次从选择章节开始
                return "打完了"
            这一局怎么结束 = ""
            进入第八章()                        # 新加：第九章 和 打完不回选择章节，同一局接着打第八章
        elif 当前生命值 <= 0:
            print(文(f"\n这一局结束了……你倒在了{当前章节} 第{显示层数(当前章节, 层数)}层第{关卡}关。",
                     f"\nEsta partida se ha acabado... Has caído en {名(当前章节)}, piso {显示层数(当前章节, 层数)}, sala {关卡}."))
            if 死亡后清空存档:
                清空存档(当前存档编号)          # 修改：只删这一局，解锁的章节还在
                print(文(">> 这一局没了，不过解锁的章节都还在。",
                         ">> Has perdido esta partida, pero los capítulos desbloqueados se quedan."))
            return "死了"
        elif 关卡 == 10:
            层数 += 1
            关卡 = 0
            print(文(f"\n★ 你来到了第{显示层数(当前章节, 层数)}层！怪物变得更强了…… ★",
                     f"\n★ ¡Llegas al piso {显示层数(当前章节, 层数)}! Los monstruos son más fuertes... ★"))

        保存存档(当前存档编号)                  # 每打完一关自动存档（死了就不存）
        # 修改：删掉了这里的 清屏()（原来要先按「回车键继续」才到下一关）：现在每次输入完就马上清屏

# ==================================================================
#                             存档
# ==================================================================

# 新加：3个存档，放在 eljuego.py 旁边的"存档"文件夹里
# 存档就是普通的文字文件，一行一项：名字=数值（例：层数=2），用记事本也能打开看
# 每打完一关自动存档；下次打开游戏选同一个存档，就从下一关继续
# 修改：每个存档分成两个文件（像以撒：死了这一局没了，解锁的东西一直在）
#       存档1.txt = 这一局（打到哪、生命值、护符、技能等级……）：死了、打完这一章 就删掉
#       进度1.txt = 永久进度（解锁的章节、打完的章节、看过的结局、解锁的天赋、快照）：只有选「删除整个存档」才会删

存档数量 = 3
死亡后清空存档 = True             # True：死了这一局就没了（解锁的章节不会没）；False：死了还能在选择存档里「继续这一局」，从上一关重新开始
# 修改：删掉了 通关后清空存档：打完一章，这一局一定会结束（回到选择章节）

try:
    游戏文件夹 = os.path.dirname(os.path.abspath(__file__))    # __file__ 是 Python 自带的，= eljuego.py 的位置 → 拿到它所在的文件夹
except NameError:
    游戏文件夹 = os.getcwd()                                  # 在 Jupyter / Colab 里没有 __file__，就用现在所在的文件夹
存档文件夹 = os.path.join(游戏文件夹, "存档")                   # os.path.join 会自动用对的斜杠（Windows 是 \，Mac/Linux 是 /）

当前存档编号 = 0                  # 现在玩的是哪个存档（1~3），选完存档才知道
这一局在打 = False                # 新加（控制台）：现在有没有在打的一局（开新游戏、读档以后 True，这一局结束 False）。控制台要看
要退出存档 = False                # 新加：在 [0] 设置 里选了退出存档 → True（战斗和这一关马上结束，回到选择存档）

# 存档里 True/False 的项目（读档、检查存档的时候要特别处理）。职业、护符列表、消耗品列表是文字，剩下的全都是数字
# 以后存档里加了新的 True/False 项目，记得也加进这个列表
# 修改：被动3解锁 → 准进阶被动解锁。"被动3解锁" 还留在这里，是给旧存档用的（不然旧存档会被当成坏掉了）
# 修改：神器 删掉了，"神器" 还留在这里也是给旧存档用的（旧存档里有 神器=False 这一行）
# 修改：已发现狂战士突破、已发现重装骑士突破 不用了（改成永久解锁：已解锁的职业），还留在这里也是给旧存档用的
布尔项目 = ["被动1解锁", "被动2解锁", "准进阶被动解锁", "被动3解锁", "已发现狂战士突破", "已发现重装骑士突破", "神器", "显示详情"]      # 修改：加了 已发现X突破
# 存档里一定要有的项目，少了就算存档坏了（选存档的时候要用它们显示简介）
必须有的项目 = ["职业", "普攻获得能量", "层数", "关卡", "当前生命值", "最大生命值", "当前持有金币"]

def 存档路径(编号):
    # 例：编号 2 → .../存档/存档2.txt（这一局）
    return os.path.join(存档文件夹, f"存档{编号}.txt")

def 进度路径(编号):
    # 新加：例：编号 2 → .../存档/进度2.txt（永久进度）
    return os.path.join(存档文件夹, f"进度{编号}.txt")

def 写入文件(路径, 所有行):
    # 新加：把 所有行 一行一行写进文件（原来写在 保存存档() 里面，现在 保存进度() 也要用，所以单独拿出来）
    # 返回 True = 写好了，False = 写不进去
    try:
        os.makedirs(存档文件夹, exist_ok=True)                  # 没有"存档"文件夹就建一个（已经有了就什么都不做）
        临时文件 = 路径 + ".tmp"
        with open(临时文件, "w", encoding="utf-8") as 文件:    # with：写完自动关掉文件；utf-8：中文不会变成乱码
            文件.write("\n".join(所有行) + "\n")
        os.replace(临时文件, 路径)                              # 先写临时文件，写完再换掉旧的：就算写到一半游戏被关掉，旧的也不会坏
        return True
    except OSError:                                             # OSError = 跟文件有关的错误（没有权限、硬盘满了……）
        return False

def 删除文件(路径):
    # 新加：删掉一个文件（原来写在 清空存档() 里面）。本来就没有这个文件也不要紧
    try:
        os.remove(路径)
    except FileNotFoundError:
        pass                                                    # 本来就没有这个文件：不用管
    except OSError:
        print(文(f">> 删除失败！可以自己去删掉：{路径}",
                 f">> ¡No se ha podido borrar! Puedes borrarlo tú a mano: {路径}"))

def 转数字(文字):
    # 存档里的东西读出来都是文字："12" → 12，"87.5" → 87.5
    # 两种都不是（比如 "abc"）就会报 ValueError
    try:
        return int(文字)
    except ValueError:
        return float(文字)

def 保存存档(编号):
    # 把玩家现在的全部进度写进存档文件，一行一项：名字=数值
    # 护符列表要先变成一行文字：["A", "B"] → "A,B"
    护符文字列表 = []
    for 护符 in 当前持有护符的列表:
        护符文字列表.append(str(护符))
    护符文字 = ",".join(护符文字列表)
    # 新加：药水列表也一样：["高级 持续 攻击力", "低级 普通 恢复生命值"] → "高级 持续 攻击力,低级 普通 恢复生命值"
    消耗品文字 = ",".join(当前持有消耗品的列表)

    所有行 = [
        # ----- 职业、进度 -----
        f"章节={当前章节}",                             # 新加：这一局是哪一章
        f"职业={行动详情_角色}",
        f"普攻获得能量={普攻获得能量}",
        f"层数={层数}",
        f"关卡={关卡}",                                 # 这一层已经打完的关卡（0 = 这一层还没开始）
        # ----- 数值 -----
        f"最大生命值={最大生命值}",
        f"当前生命值={当前生命值}",
        f"当前护盾={当前护盾}",
        f"基础攻击力={基础攻击力}",
        f"当前攻击力={当前攻击力}",
        f"基础防御力={基础防御力}",
        f"当前防御力={当前防御力}",
        f"基础命中率={基础命中率}",
        f"当前命中率={当前命中率}",
        f"基础暴击率={基础暴击率}",
        f"当前暴击率={当前暴击率}",
        f"基础暴击伤害={基础暴击伤害}",
        f"当前暴击伤害={当前暴击伤害}",
        f"基础幸运={基础幸运}",
        f"当前幸运={当前幸运}",
        f"当前能量={当前能量}",
        f"能量上限={能量上限}",
        # ----- 金币、护符、消耗品 -----（修改：删掉了 神器，加了 消耗品）
        f"当前持有金币={当前持有金币}",
        f"当前持有护符的数量={当前持有护符的数量}",
        f"当前持有护符的列表={护符文字}",
        f"最大持有护符的数量={最大持有护符的数量}",
        f"当前持有消耗品的列表={消耗品文字}",                 # 新加：身上的药水
        # ----- 天赋 -----（新加，第三步）
        f"当前持有天赋的列表={','.join(当前持有天赋的列表)}",   # 例：尸狗,愤怒,宽容
        f"本局祝福次数={本局祝福次数}",
        # ----- 额外加成、伤害加成/减免 -----
        f"额外生命值加成={额外生命值加成}",
        f"额外攻击力加成={额外攻击力加成}",
        f"额外防御力加成={额外防御力加成}",
        f"额外命中率加成={额外命中率加成}",
        f"额外暴击率加成={额外暴击率加成}",
        f"额外暴击伤害加成={额外暴击伤害加成}",
        f"额外幸运加成={额外幸运加成}",
        f"额外获得金币加成={额外获得金币加成}",
        f"受到的伤害加成={受到的伤害加成}",
        f"受到的伤害减免={受到的伤害减免}",
        f"造成的伤害加成={造成的伤害加成}",
        f"造成的伤害减免={造成的伤害减免}",
        # ----- 技能等级 -----
        f"普攻等级={普攻等级}",
        f"技能1等级={技能1等级}",
        f"技能2等级={技能2等级}",
        f"大招等级={大招等级}",
        f"被动1等级={被动1等级}",
        f"被动2等级={被动2等级}",
        f"被动1解锁={被动1解锁}",
        f"被动2解锁={被动2解锁}",
        f"准进阶被动解锁={准进阶被动解锁}",                 # 修改：原来是 被动3等级、被动3解锁 两行
        # 修改：删掉了 已发现狂战士突破、已发现重装骑士突破（改成永久解锁，存在 进度N.txt 的 已解锁的职业 里）
        # ----- 设置 -----
        f"显示详情={显示详情}",
    ]

    # 修改：写文件的部分挪到了 写入文件() 里面（保存进度() 也要用）
    if 写入文件(存档路径(编号), 所有行):
        print(文(f">> 已自动存档（存档{编号}）", f">> Guardado automático (archivo {编号})"))
    else:
        print(文(f">> 存档{编号}保存失败！看看这个文件夹能不能放文件：{存档文件夹}",
                 f">> ¡No se ha podido guardar el archivo {编号}! Mira si se pueden guardar archivos en esta carpeta: {存档文件夹}"))

def 清空存档(编号):
    # 修改：只删这一局（存档N.txt）。解锁的章节、看过的结局在 进度N.txt 里，不会删
    删除文件(存档路径(编号))

def 删除整个存档(编号):
    # 新加：这一局 + 永久进度 全部删掉，这个存档变回空的（选择存档里的「删除整个存档」）
    删除文件(存档路径(编号))
    删除文件(进度路径(编号))

def 保存进度(编号):
    # 新加：把永久进度写进 进度N.txt。列表用逗号连起来：["第一章", "第二章"] → "第一章,第二章"
    所有行 = [
        f"已解锁的章节={','.join(已解锁的章节)}",
        f"已打完的章节={','.join(已打完的章节)}",
        f"已看过的结局={','.join(已看过的结局)}",
        f"已解锁的天赋={','.join(已解锁的天赋)}",
        f"已解锁的职业={','.join(已解锁的职业)}",                 # 新加：永久解锁的进阶职业
    ]
    for 位置 in range(len(快照_名字)):
        所有行.append(f"快照_{快照_名字[位置]}={已存的快照[位置]}")     # 新加（第五步）：例：快照_第六章的你=战士,250,180.5,60,90,25,300
    if not 写入文件(进度路径(编号), 所有行):
        print(文(f">> 进度{编号}保存失败！看看这个文件夹能不能放文件：{存档文件夹}",
                 f">> ¡No se ha podido guardar el progreso {编号}! Mira si se pueden guardar archivos en esta carpeta: {存档文件夹}"))

def 拆成列表(文字):
    # 新加：进度文件里的列表用这个读："第一章, 第九章  阴" → ["第一章", "第九章 阴"]
    # 多余的空格去掉（用记事本改过也不怕），空的、重复的不要
    列表 = []
    for 一项 in 文字.split(","):
        一项 = " ".join(一项.split())
        if 一项 != "" and 一项 not in 列表:
            列表.append(一项)
    return 列表

def 进度没坏(名字列表, 数值列表):
    # 新加：检查进度文件有没有被改坏：章节的名字都要在 章节列表 里，天赋的名字都要在 天赋名字列表 里
    # 修改（第四步）：结局的名字也要在 结局名字列表 里
    for 位置 in range(len(名字列表)):
        if 名字列表[位置] == "已解锁的章节" or 名字列表[位置] == "已打完的章节":
            for 章节 in 拆成列表(数值列表[位置]):
                if 章节 not in 章节列表:
                    return False
        elif 名字列表[位置] == "已解锁的天赋":
            for 名字 in 拆成列表(数值列表[位置]):
                if 名字 not in 天赋名字列表:
                    return False
        elif 名字列表[位置] == "已解锁的职业":                    # 新加：职业的名字都要在 进阶职业 里
            for 名字 in 拆成列表(数值列表[位置]):
                if 名字 not in 进阶职业:
                    return False
        elif 名字列表[位置] == "已看过的结局":
            for 结局 in 拆成列表(数值列表[位置]):
                if 结局 not in 结局名字列表:
                    return False
        elif 名字列表[位置].startswith("快照_"):
            if not 快照没坏(数值列表[位置]):             # 新加（第五步）：快照的格式要对（不然拿来当敌人的时候会出错）
                return False
    return True

def 进度简介文字(解锁的章节, 看过的结局):
    # 新加：显示用。例："已解锁3/11章，看过1个结局"（没看过结局就不写）
    # 修改（第四步）：结局10（前一半） 不算（看 结局数量()）
    简介 = 文(f"已解锁{len(解锁的章节)}/{len(章节列表)}章",
              f"{len(解锁的章节)}/{len(章节列表)} capítulos desbloqueados")
    if 结局数量(看过的结局) > 0:
        简介 += 文(f"，看过{结局数量(看过的结局)}个结局", f", {结局数量(看过的结局)} finales vistos")
    return 简介

def 读取进度简介(编号):
    # 新加：选存档的时候用：返回 状态 和 简介。状态是 "空" / "正常" / "损坏"（跟 读取存档简介() 一样）
    try:
        名字列表, 数值列表 = 读取文件(进度路径(编号))
    except UnicodeDecodeError:                                      # 文件不是 utf-8（比如用别的编码另存过）
        return "损坏", 文("进度已损坏（读不出来）", "Progreso roto (no se puede leer)")
    if not 进度没坏(名字列表, 数值列表):
        return "损坏", 文("进度已损坏（读不出来）", "Progreso roto (no se puede leer)")
    解锁的章节 = ["第一章"]
    看过的结局 = []
    for 位置 in range(len(名字列表)):
        if 名字列表[位置] == "已解锁的章节":
            解锁的章节 = 拆成列表(数值列表[位置])
            if "第一章" not in 解锁的章节:
                解锁的章节.insert(0, "第一章")
        elif 名字列表[位置] == "已看过的结局":
            看过的结局 = 拆成列表(数值列表[位置])
    if len(名字列表) == 0:
        return "空", 进度简介文字(解锁的章节, 看过的结局)
    return "正常", 进度简介文字(解锁的章节, 看过的结局)

def 读取进度(编号):
    # 新加：打开存档的时候调用：把 进度N.txt 里的东西放回变量里（进度没坏() 检查过才会调用）
    #       没有进度文件（新的存档、以前版本的旧存档）→ 只解锁了第一章
    global 已解锁的章节, 已打完的章节, 已看过的结局, 已解锁的天赋, 已解锁的职业, 已存的快照
    已解锁的章节 = ["第一章"]
    已打完的章节 = []
    已看过的结局 = []
    已解锁的天赋 = []
    已解锁的职业 = []                               # 新加：以前的进度文件里没有这一行 → 一个都还没解锁
    已存的快照 = [""] * len(快照_名字)               # 新加（第五步）：[""] * 4 = ["", "", "", ""]（一个快照都还没存）
    名字列表, 数值列表 = 读取文件(进度路径(编号))
    for 位置 in range(len(名字列表)):
        名字 = 名字列表[位置]
        数值 = 数值列表[位置]
        if 名字 == "已解锁的章节":
            已解锁的章节 = 拆成列表(数值)
        elif 名字 == "已打完的章节":
            已打完的章节 = 拆成列表(数值)
        elif 名字 == "已看过的结局":
            已看过的结局 = 拆成列表(数值)
        elif 名字 == "已解锁的天赋":
            已解锁的天赋 = 拆成列表(数值)
        elif 名字 == "已解锁的职业":
            已解锁的职业 = 拆成列表(数值)
        elif 名字.startswith("快照_") and " ".join(名字[3:].split()) in 快照_名字:
            # 新加（第五步）："快照_第六章的你" → 名字[3:] = "第六章的你"（去掉前面3个字：快、照、_）
            已存的快照[快照_名字.index(" ".join(名字[3:].split()))] = 数值
        # 不认识的名字就不管它
    if "第一章" not in 已解锁的章节:
        已解锁的章节.insert(0, "第一章")          # 第一章一直都能玩

def 设置():
    # 新加：战斗里的 [0] 设置：退出这个存档（回到选择存档，可以玩别的存档）
    # 返回 True = 确定要退出，False = 不退出（回到战斗，不算回合）
    # 修改（语言）：加了 [2] 语言 / Idioma。换完语言再显示一次设置（已经是新的语言了），按 [0] 回到战斗
    while True:
        print(文("\n========== 设置 ==========", "\n========== Ajustes =========="))
        print(文("[1] 退出这个存档（回到选择存档）", "[1] Salir de este archivo (volver a elegir archivo)"))
        print("[2] 语言 / Idioma")                       # 两种语言都写上：选错了语言也找得到
        print(文("[0] 返回", "[0] Volver"))
        选择 = 输入数字(文("请选择: ", "Elige: "), 0, 2)
        if 选择 == 0:
            return False
        if 选择 == 1:
            break
        选择语言()                                      # 选择 == 2
    # 存档是打完一关才存的，所以这一关打到一半退出的话，这一关就白打了
    print(文(f">> 退出以后，这一关（第{显示层数(当前章节, 层数)}层第{关卡}关）的进度不会保存，下次从这一关重新开始。",
             f">> Si sales, no se guarda lo que llevas de esta sala (piso {显示层数(当前章节, 层数)}, sala {关卡}), y la próxima vez vuelves a empezar desde esta sala."))
    return 输入数字(文("[1] 确定退出  [0] 再想想: ", "[1] Sí, salir  [0] Mejor me lo pienso: "), 0, 1) == 1

def 读取存档文件(编号):
    # 修改：读文件的部分挪到了 读取文件() 里面（进度文件也要用）
    return 读取文件(存档路径(编号))

def 读取文件(路径):
    # 把 名字=数值 的文件拆成两个列表：名字列表[0] 和 数值列表[0] 是一对，[1] 和 [1] 是一对……
    # 没有这个文件 → 两个列表都是空的 = 空存档
    # 修改：原来叫 读取存档文件(编号)，现在传的是路径（存档、进度 都用这个）
    名字列表 = []
    数值列表 = []
    try:
        with open(路径, "r", encoding="utf-8-sig") as 文件:                # utf-8-sig：用记事本改过的存档也能读
            for 这一行 in 文件:
                这一行 = 这一行.strip()                             # 去掉行尾的换行和空格
                if "=" in 这一行:                                   # 不是 名字=数值 的行（比如空行）就跳过
                    名字, 数值 = 这一行.split("=", 1)               # 只按第一个 = 切成两半："层数=2" → "层数" 和 "2"
                    名字列表.append(名字.strip())
                    数值列表.append(数值.strip())
    except OSError:
        pass                                                        # 没有这个文件（或者打不开）= 空存档
    return 名字列表, 数值列表                                       # 一次返回两个列表，接的时候也用两个变量接

def 存档没坏(名字列表, 数值列表):
    # 检查存档有没有被改坏：必须有的项目都要有、职业要是4个职业（或者转职以后的职业）之一、
    # True/False 的项目只能是 True 或 False、剩下的都得是数字
    for 名字 in 必须有的项目:
        if 名字 not in 名字列表:
            return False
    for 位置 in range(len(名字列表)):
        名字 = 名字列表[位置]
        数值 = 数值列表[位置]
        if 名字 == "职业":
            if 数值 not in 职业 and 数值 not in 进阶职业:      # 修改：狂战士、重装骑士 也算
                return False
        elif 名字 == "章节":
            if " ".join(数值.split()) not in 章节列表:        # 新加：章节的名字要对（"第九章  阴" 多打了空格也没关系）
                return False
        elif 名字 == "当前持有护符的列表":
            # 修改：原来写什么都行；现在每个护符都要是 "品质 种类"（例："史诗 玛瑙"），不然算加成的时候会出错
            if 数值 != "":
                for 护符 in 数值.split(","):
                    if not 护符没坏(护符):
                        return False
        elif 名字 == "当前持有消耗品的列表":
            # 新加：每瓶药水都要是 "品质 类型 效果"（例："高级 持续 攻击力"），不然喝的时候会出错
            if 数值 != "":
                for 药水 in 数值.split(","):
                    if not 药水没坏(药水):
                        return False
        elif 名字 == "当前持有天赋的列表":
            # 新加（第三步）：每个天赋都要是 天赋名字列表 里的名字，不然算加成的时候会出错
            for 天赋 in 拆成列表(数值):
                if 天赋 not in 天赋名字列表:
                    return False
        elif 名字 in 布尔项目:
            if 数值 != "True" and 数值 != "False":
                return False
        else:
            try:
                转数字(数值)
            except ValueError:
                return False
    return True

def 读取存档简介(编号):
    # 选存档的时候用：返回 状态 和 简介。状态是 "空" / "正常" / "损坏"
    try:
        名字列表, 数值列表 = 读取存档文件(编号)
    except UnicodeDecodeError:                                      # 文件不是 utf-8（比如用别的编码另存过）
        return "损坏", 文("已损坏（读不出来）", "Roto (no se puede leer)")
    if len(名字列表) == 0:
        return "空", 文("空", "Vacío")
    if not 存档没坏(名字列表, 数值列表):
        return "损坏", 文("已损坏（读不出来）", "Roto (no se puede leer)")

    # index() 找到这个名字在第几个位置，再去 数值列表 的同一个位置拿数值
    存档职业 = 数值列表[名字列表.index("职业")]
    存档章节 = "第一章"                                              # 新加：以前的旧存档里没有 章节 → 当成第一章
    if "章节" in 名字列表:
        存档章节 = " ".join(数值列表[名字列表.index("章节")].split())
    存档层数 = 转数字(数值列表[名字列表.index("层数")])
    存档关卡 = 转数字(数值列表[名字列表.index("关卡")])
    存档生命值 = 转数字(数值列表[名字列表.index("当前生命值")])
    存档最大生命值 = 转数字(数值列表[名字列表.index("最大生命值")])
    if "额外生命值加成" in 名字列表:                                # 新加：生命值上限要加上护符加的生命值（翡翠）
        存档最大生命值 += 转数字(数值列表[名字列表.index("额外生命值加成")])
    if "当前持有天赋的列表" in 名字列表:                            # 新加（第三步）：还有天赋加的 最大生命值%（跟 生命值上限() 一样算）
        存档天赋 = 拆成列表(数值列表[名字列表.index("当前持有天赋的列表")])
        存档最大生命值 += 转数字(数值列表[名字列表.index("最大生命值")]) * 天赋列表加成(存档天赋, "最大生命值%") / 100
    存档金币 = 转数字(数值列表[名字列表.index("当前持有金币")])
    存档层数 = 显示层数(存档章节, 存档层数)                          # 新加：第九章、第八章 的层数显示成负的
    简介 = 文(f"{存档章节} {存档职业} | 下一关: 第{存档层数}层第{存档关卡 + 1}关 | 生命值【{生命值文字(存档生命值)}/{round(存档最大生命值)}】| 金币【{存档金币}G】",
              f"{名(存档章节)} {名(存档职业)} | Siguiente: piso {存档层数}, sala {存档关卡 + 1} | Vida【{生命值文字(存档生命值)}/{round(存档最大生命值)}】| Monedas【{存档金币}G】")
    return "正常", 简介

def 读取存档(编号):
    # 读档：把存档里的数值放回游戏的变量里（存档没坏() 检查过才会调用，所以这里不会出错）
    global 行动详情_角色, 普攻获得能量, 层数, 关卡
    global 最大生命值, 当前生命值, 当前护盾, 基础攻击力, 当前攻击力, 基础防御力, 当前防御力, 基础命中率, 当前命中率
    global 基础暴击率, 当前暴击率, 基础暴击伤害, 当前暴击伤害, 基础幸运, 当前幸运, 当前能量, 能量上限
    global 当前持有金币, 当前持有护符的数量, 当前持有护符的列表, 最大持有护符的数量, 当前持有消耗品的列表     # 修改：神器 → 当前持有消耗品的列表
    global 额外生命值加成, 额外攻击力加成, 额外防御力加成, 额外命中率加成, 额外暴击率加成, 额外暴击伤害加成, 额外幸运加成, 额外获得金币加成
    global 受到的伤害加成, 受到的伤害减免, 造成的伤害加成, 造成的伤害减免
    global 普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级, 被动1解锁, 被动2解锁, 准进阶被动解锁
    global 显示详情, 当前章节, 当前持有天赋的列表, 本局祝福次数, 这一局在打

    重置所有数值()          # 新加：先把上一个存档的东西全部清掉（在设置里退出存档以后再读别的存档，不然会混在一起）
    名字列表, 数值列表 = 读取存档文件(编号)
    for 位置 in range(len(名字列表)):
        名字 = 名字列表[位置]
        数值 = 数值列表[位置]

        # ----- 职业、进度 -----
        if 名字 == "章节":
            当前章节 = " ".join(数值.split())         # 新加：以前的旧存档里没有这一行 → 还是 重置所有数值() 里的第一章
        elif 名字 == "职业":
            行动详情_角色 = 数值
        elif 名字 == "普攻获得能量":
            普攻获得能量 = 转数字(数值)
