# 新加（语言）：参数用编号的时候，编号对应的东西（从1开始数）。天赋、护符、药水、章节、结局、快照 直接用它们自己的列表
控制台数值名字 = ["最大生命值", "攻击力", "防御力", "命中率", "暴击率", "暴击伤害", "幸运"]          # /stat 的编号
控制台技能名字 = ["普攻", "技能1", "技能2", "大招", "被动1", "被动2", "准进阶被动"]               # /skill 的编号（跟锻炼里的 [1]~[7] 一样）

def 控制台(指令文字):
    # 开发者模式里输入了 / 开头的东西（读输入() 调用）
    # /gold 999 → 只执行这一个；只输入 / → 进入控制台，一直输指令，输入 exit（或者空着按回车）回到游戏
    if 指令文字.strip() != "":
        执行指令(指令文字)
        return
    print(文("\n========== 控制台（输入 help 看全部指令；输入 exit 或者直接按回车 回到游戏）==========",
             "\n========== Consola (escribe help para ver los comandos; exit o Enter para volver al juego) =========="))
    while True:
        一行 = input(文("控制台> ", "Consola> ")).strip()
        if 一行[:1] in 控制台开头:
            一行 = 一行[1:].strip()                    # 多打了 / 也没关系
        if 一行 == "" or 一行.lower() == "exit":
            print(文(">> 关掉了控制台，回到游戏。", ">> Consola cerrada, vuelves al juego."))
            return
        执行指令(一行)

def 执行指令(一行):
    # 一行指令 → 按空格拆成 指令 + 参数 → 交给对应的 控制台_X() 去做
    # 例："talent 1-7 10" → 指令 = "talent"，参数 = ["1-7", "10"]
    # 修改（语言）：指令改成了英文。lower() = 变成小写，所以 GOLD、Gold 也行
    拆开 = 一行.split()
    指令 = 拆开[0].lower()
    参数 = 拆开[1:]
    if 指令 == "help" or 指令 == "?" or 指令 == "？":
        控制台_帮助()
    elif 指令 == "show":
        控制台_看()
    elif 指令 == "gold":
        控制台_金币(参数)
    elif 指令 == "hp":
        控制台_生命值(参数)
    elif 指令 == "heal":
        控制台_满血()
    elif 指令 == "stat":
        控制台_数值(参数)
    elif 指令 == "energy":
        控制台_能量(参数)
    elif 指令 == "talent":
        控制台_天赋(参数)
    elif 指令 == "deltalent":
        控制台_去掉天赋(参数)
    elif 指令 == "amulet":
        控制台_护符(参数)
    elif 指令 == "potion":
        控制台_药水(参数)
    elif 指令 == "skill":
        控制台_技能(参数)
    elif 指令 == "class":
        控制台_转职(参数)
    elif 指令 == "jump":
        控制台_跳(参数)
    elif 指令 == "kill":
        控制台_杀()
    elif 指令 == "blessings":
        控制台_祝福次数(参数)
    elif 指令 == "route":
        控制台_路线()
    elif 指令 == "testmode":
        控制台_测试模式()
    elif 指令 == "unlock":
        控制台_解锁(参数)
    elif 指令 == "ending":
        控制台_结局(参数)
    elif 指令 == "finish":
        控制台_打完(参数)
    elif 指令 == "snapshot":
        控制台_快照(参数)
    elif 指令 == "save":
        控制台_存档()
    elif 指令 == "exit":
        print(文(">> 控制台没有开着（只输入一个 / 才会进入控制台）。", ">> La consola no está abierta (para entrar escribe solo /)."))
    else:
        print(文(f">> 没有这个指令：{指令}（输入 /help 看全部指令）", f">> Ese comando no existe: {指令} (escribe /help para ver todos)"))

# ---------------------------- 控制台用的小工具 ----------------------------

def 指令数字(文字):
    # 参数变成数字："999" → 999，"12.5" → 12.5；不是数字 → None（None = 什么都没有）
    try:
        return 转数字(文字)
    except ValueError:
        return None

def 第几个(文字, 名字们):
    # 新加（语言）：参数里的编号（从1开始数）→ 名字们 里的那个名字。例：第几个("2", 护符种类列表) → "琥珀"
    # 不是整数、超出范围 → None
    数 = 指令数字(文字)
    if 数 is None or 数 != int(数) or 数 < 1 or 数 > len(名字们):
        return None
    return 名字们[int(数) - 1]

def 指令编号们(参数, 一共几个):
    # 新加（语言）：好几个编号 → 一串位置（从0开始，可以直接拿来用 列表[位置]）
    # 可以写：单个编号（3）、范围（1-7 或者 1~7 = 1到7）、all（= 全部）。例：["1-3", "7"] → [0, 1, 2, 6]
    # 有一个写错（不是数字、超出 1~一共几个）→ 返回 None
    位置们 = []
    for 一个 in 参数:
        一个 = 一个.replace("~", "-")
        if 一个.lower() == "all":
            起 = 1
            止 = 一共几个
        elif "-" in 一个:
            两头 = 一个.split("-", 1)               # "1-7" → ["1", "7"]
            起 = 指令数字(两头[0])
            止 = 指令数字(两头[1])
        else:
            起 = 指令数字(一个)
            止 = 起
        if 起 is None or 止 is None or 起 != int(起) or 止 != int(止) or 起 < 1 or 止 > 一共几个 or 起 > 止:
            return None
        for 编号 in range(int(起), int(止) + 1):
            if 编号 - 1 not in 位置们:                # 重复写的只算一次
                位置们.append(编号 - 1)
    return 位置们

def 编号列表(名字们):
    # 新加（语言）：显示用：一串名字加上编号，翻译成现在的语言。例：["玛瑙", "琥珀"] → "1 玛瑙  2 琥珀" / "1 Ágata  2 Ámbar"
    文字们 = []
    for 位置 in range(len(名字们)):
        文字们.append(f"{位置 + 1} {名(名字们[位置])}")
    return "  ".join(文字们)

def 开关文字(开):
    # 显示用：True → "开"，False → "关"（西班牙语：sí / no）
    if 开:
        return 文("开", "sí")
    return 文("关", "no")

def 技能等级文字():
    # 新加（语言）：显示用：每个技能、被动现在几级（/show、/skill 都要用，原来写了两遍）
    return 文(f"技能等级：普攻 {普攻等级} | 技能1 {技能1等级} | 技能2 {技能2等级} | 大招 {大招等级} | 被动1 {被动1等级} | 被动2 {被动2等级} | 准进阶被动：{开关文字(准进阶被动解锁)}",
              f"Niveles: Ataque básico {普攻等级} | Habilidad 1 {技能1等级} | Habilidad 2 {技能2等级} | Definitiva {大招等级} | Pasiva 1 {被动1等级} | Pasiva 2 {被动2等级} | Pasiva pre-avanzada: {开关文字(准进阶被动解锁)}")

def 在玩吗():
    # 现在有没有在打的一局（开好新游戏、读好档了）。没有 → 提示一下，返回 False
    if not 这一局在打:
        print(文(">> 现在没有在打的一局（先选存档、开始一局），这个指令现在用不了。",
                 ">> Ahora no hay ninguna partida en curso (elige archivo y empieza una), así que este comando no se puede usar."))
        return False
    return True

def 选了存档吗():
    # 选好存档了吗（解锁、结局、快照 这些要存进 进度N.txt）。还没有 → 提示一下，返回 False
    if 当前存档编号 == 0:
        print(文(">> 还没选存档，这个指令现在用不了。", ">> Todavía no has elegido archivo, así que este comando no se puede usar."))
        return False
    return True

def 这种天赋(种类):
    # 某一种天赋的全部名字（例："成神的道路" → 七魄 + 三魂）
    名字们 = []
    for 位置 in range(len(天赋名字列表)):
        if 天赋种类列表[位置] == 种类:
            名字们.append(天赋名字列表[位置])
    return 名字们

def 控制台_天赋编号():
    # 新加（语言）：列出天赋的编号，按种类分三行（1~10 成神的道路、11~20 恶魔的低语、21~30 天使的馈赠）
    for 种类 in ["成神的道路", "恶魔的低语", "天使的馈赠"]:
        文字们 = []
        for 位置 in range(len(天赋名字列表)):
            if 天赋种类列表[位置] == 种类:
                文字们.append(f"{位置 + 1} {名(天赋名字列表[位置])}")
        print(f"     【{名(种类)}】{'  '.join(文字们)}")

