    # 新加（语言）：/help 下面显示的：每个指令的参数编号是什么
    print(文("---------- 参数的编号（从1开始；好几个可以写 1-7；all = 全部）----------",
             "---------- Números de los comandos (empiezan en 1; varios: 1-7; all = todos) ----------"))
