    print(文(f"  amulet 品质：{编号列表(护符品质列表)}", f"  amulet calidad: {编号列表(护符品质列表)}"))
    print(文(f"  amulet 种类：{编号列表(护符种类列表)}", f"  amulet tipo: {编号列表(护符种类列表)}"))
    print(文(f"  potion 品质：{编号列表(药水品质列表)}", f"  potion calidad: {编号列表(药水品质列表)}"))
    print(文(f"  potion 类型：{编号列表(药水类型列表)}", f"  potion tipo: {编号列表(药水类型列表)}"))
    print(文(f"  potion 效果：{编号列表(药水效果列表)}", f"  potion efecto: {编号列表(药水效果列表)}"))
    print(文(f"  unlock chapter / finish（章节）：{编号列表(章节显示顺序)}", f"  unlock chapter / finish (capítulos): {编号列表(章节显示顺序)}"))
    print(文(f"  ending：{编号列表(结局名字列表)}", f"  ending: {编号列表(结局名字列表)}"))
    print(文(f"  snapshot save：{编号列表(快照_名字)}", f"  snapshot save: {编号列表(快照_名字)}"))
    print(文("  talent / deltalent / unlock talent（天赋）：", "  talent / deltalent / unlock talent (talentos):"))
    控制台_天赋编号()

