def 控制台_数值(参数):
    # 修改（语言）：名字 → 编号（看 控制台数值名字：1 最大生命值 …… 7 幸运）
    global 最大生命值, 基础攻击力, 基础防御力, 基础命中率, 基础暴击率, 基础暴击伤害, 基础幸运
    if not 在玩吗():
        return
    名字 = None
    if len(参数) == 2 and 指令数字(参数[1]) is not None:
        名字 = 第几个(参数[0], 控制台数值名字)
    if 名字 is None:
        print(文(">> 用法：stat 编号 数量（例：stat 2 500 = 攻击力 500）", ">> Uso: stat número cantidad (ej.: stat 2 500 = ataque 500)"))
        print(f"   {编号列表(控制台数值名字)}")
        return
    数 = 指令数字(参数[1])
    if 名字 == "最大生命值":
        最大生命值 = 数
    elif 名字 == "攻击力":
        基础攻击力 = 数
    elif 名字 == "防御力":
        基础防御力 = 数
    elif 名字 == "命中率":
        基础命中率 = 数
    elif 名字 == "暴击率":
        基础暴击率 = 数
    elif 名字 == "暴击伤害":
        基础暴击伤害 = 数
    else:
        基础幸运 = 数
    更新最终数值()                                      # 基础数值变了，当前X 要重新算
    print(文(f">> 改好了：生命值上限 {round(生命值上限())} | 攻击力 {数值文字(当前攻击力)} | 防御力 {数值文字(当前防御力)}",
             f">> Hecho: vida máx. {round(生命值上限())} | ataque {数值文字(当前攻击力)} | defensa {数值文字(当前防御力)}") +
          文(f" | 命中率 {数值文字(当前命中率)} | 暴击率 {数值文字(当前暴击率)} | 暴击伤害 {数值文字(当前暴击伤害)} | 幸运 {数值文字(当前幸运)}",
             f" | precisión {数值文字(当前命中率)} | prob. crítico {数值文字(当前暴击率)} | daño crítico {数值文字(当前暴击伤害)} | suerte {数值文字(当前幸运)}"))

