def 控制台_天赋(参数):
    # 修改（语言）：名字 → 编号（1~30，看 /help）。原来的 七魄 / 成神 / 恶魔 / 天使 / 全部 → 1-7 / 1-10 / 11-20 / 21-30 / all
    if not 在玩吗():
        return
    位置们 = 指令编号们(参数, len(天赋名字列表))
    if len(参数) == 0 or 位置们 is None:
        print(文(">> 用法：talent 编号……（可以写好几个；1-7 = 1到7；all = 全部。例：talent 1-7 10 = 七魄 + 人魂）",
                 ">> Uso: talent número... (puedes poner varios; 1-7 = del 1 al 7; all = todos. Ej.: talent 1-7 10 = las 7 Emociones + Mente)"))
        控制台_天赋编号()
        return
    for 位置 in 位置们:
        名字 = 天赋名字列表[位置]
        if 有天赋(名字):
            print(文(f">> 已经有【{名字}】了", f">> Ya tienes【{名(名字)}】"))
        else:
            获得天赋(名字)

def 控制台_去掉天赋(参数):
    if not 在玩吗():
        return
    if len(参数) == 1 and 参数[0].lower() == "all":
        for 名字 in list(当前持有天赋的列表):          # list() = 复制一份：一边去掉一边看原来的列表会乱掉
            去掉天赋(名字)
        return
    位置们 = 指令编号们(参数, len(天赋名字列表))
    if len(参数) == 0 or 位置们 is None:
        print(文(">> 用法：deltalent 编号……（编号跟 talent 的一样；deltalent all = 全部去掉）",
                 ">> Uso: deltalent número... (los mismos números que talent; deltalent all = quitarte todos)"))
        控制台_天赋编号()
        return
    for 位置 in 位置们:
        名字 = 天赋名字列表[位置]
        if 有天赋(名字):
            去掉天赋(名字)
        else:
            print(文(f">> 身上没有这个天赋：{名字}", f">> No llevas este talento: {名(名字)}"))

def 控制台_护符(参数):
    # 修改（语言）：品质、种类 → 编号（品质 1 平凡 …… 6 唯一；种类 1 玛瑙 …… 5 翡翠）
    if not 在玩吗():
        return
    if len(参数) == 1 and 参数[0].lower() == "clear":
        while 当前持有护符的数量 > 0:
            扔掉护符(0)
        return
    品质 = None
    种类 = None
    if len(参数) == 2:
        品质 = 第几个(参数[0], 护符品质列表)
        种类 = 第几个(参数[1], 护符种类列表)
    if 品质 is None or 种类 is None:
        print(文(">> 用法：amulet 品质 种类（例：amulet 5 1 = 传奇 玛瑙）；amulet clear = 身上的护符全部扔掉",
                 ">> Uso: amulet calidad tipo (ej.: amulet 5 1 = ágata legendaria); amulet clear = tirar todos tus amuletos"))
        print(文(f"   品质：{编号列表(护符品质列表)}", f"   Calidad: {编号列表(护符品质列表)}"))
        print(文(f"   种类：{编号列表(护符种类列表)}", f"   Tipo: {编号列表(护符种类列表)}"))
        return
    新护符 = f"{品质} {种类}"
    print(文(f">> 获得了护符【{护符说明(新护符)}】！", f">> ¡Consigues el amuleto【{护符说明(新护符)}】!"))
    收下护符(新护符)

def 控制台_药水(参数):
    # 修改（语言）：品质、类型、效果 → 编号
    if not 在玩吗():
        return
    药水 = ""
    if len(参数) == 3:
        品质 = 第几个(参数[0], 药水品质列表)
        类型 = 第几个(参数[1], 药水类型列表)
        效果 = 第几个(参数[2], 药水效果列表)
        if 品质 is not None and 类型 is not None and 效果 is not None:
            药水 = f"{品质} {类型} {效果}"
    if 药水 == "" or not 药水没坏(药水):
        print(文(">> 用法：potion 品质 类型 效果（例：potion 5 3 7 = 圣级 不可逆 幸运）",
                 ">> Uso: potion calidad tipo efecto (ej.: potion 5 3 7 = poción sagrada permanente de suerte)"))
        print(文(f"   品质：{编号列表(药水品质列表)}", f"   Calidad: {编号列表(药水品质列表)}"))
        print(文(f"   类型：{编号列表(药水类型列表)}", f"   Tipo: {编号列表(药水类型列表)}"))
        print(文(f"   效果：{编号列表(药水效果列表)}", f"   Efecto: {编号列表(药水效果列表)}"))
        print(文(">> 注意：最大生命值、幸运 只有不可逆；恢复生命值 只有普通、强效",
                 ">> Ojo: vida máx. y suerte solo existen como permanente; curación solo como normal o fuerte"))
        return
    当前持有消耗品的列表.append(药水)
    print(文(f">> 获得了【{药水说明(药水)}】！", f">> ¡Consigues【{药水说明(药水)}】!"))

def 控制台_技能(参数):
    # 修改（语言）：名字 → 编号（看 控制台技能名字：1 普攻 …… 6 被动2，7 准进阶被动），跟锻炼里的 [1]~[7] 一样
    #              原来的 技能 准进阶 → skill 7 1（skill 7 0 = 锁回去）
    global 普攻等级, 技能1等级, 技能2等级, 大招等级, 被动1等级, 被动2等级, 被动1解锁, 被动2解锁, 准进阶被动解锁
    if not 在玩吗():
        return
    等级们 = [0, 1, 2, 3, 4, 5]
    名字 = None
    if len(参数) == 2:
        名字 = 第几个(参数[0], 控制台技能名字)
    if len(参数) == 1 and 指令数字(参数[0]) in 等级们:
        等级 = int(指令数字(参数[0]))
        普攻等级 = 等级
        技能1等级 = 等级
        技能2等级 = 等级
        大招等级 = 等级
        被动1等级 = 等级
        被动2等级 = 等级
        被动1解锁 = 等级 > 0                              # 被动 lv0 = 没解锁
        被动2解锁 = 等级 > 0
    elif 名字 is not None and 指令数字(参数[1]) in 等级们:
        等级 = int(指令数字(参数[1]))
        if 名字 == "准进阶被动":
            if not 有准进阶被动():
                print(文(">> 这个职业还没有准进阶被动。", ">> Esta clase todavía no tiene pasiva pre-avanzada."))
                return
            准进阶被动解锁 = 等级 > 0                     # 准进阶被动解锁即满级，没有等级：0 = 锁回去，1~5 = 解锁
        elif 名字 == "普攻":
            普攻等级 = 等级
        elif 名字 == "技能1":
            技能1等级 = 等级
        elif 名字 == "技能2":
            技能2等级 = 等级
        elif 名字 == "大招":
            大招等级 = 等级
        elif 名字 == "被动1":
            被动1等级 = 等级
            被动1解锁 = 等级 > 0
        else:
            被动2等级 = 等级
            被动2解锁 = 等级 > 0
    else:
        print(文(">> 用法：skill 等级（0~5，全部一起改）/ skill 编号 等级（只改一个）/ skill 7 1 = 解锁准进阶被动（skill 7 0 = 锁回去）",
                 ">> Uso: skill nivel (0~5, todas a la vez) / skill número nivel (solo una) / skill 7 1 = desbloquear la pasiva pre-avanzada (skill 7 0 = bloquearla)"))
        print(f"   {编号列表(控制台技能名字)}")
        return
    更新最终数值()                                       # 准进阶被动会改攻击力
    更新技能()                                           # 等级变了，重新生成 当前技能等级 和 行动详情
    print(">> " + 技能等级文字())

def 控制台_转职(参数):
    # 修改（语言）：职业 → 编号（1 狂战士，2 重装骑士，3 荆棘盾兵，4 前线装甲）
    if not 在玩吗():
        return
    新职业 = None
    if len(参数) == 1:
        新职业 = 第几个(参数[0], 进阶职业)
    if 新职业 is None:
        print(文(f">> 用法：class 编号（{编号列表(进阶职业)}）", f">> Uso: class número ({编号列表(进阶职业)})"))
        return
    原职业 = 进阶职业的原职业[进阶职业.index(新职业)]          # 修改：坦克也能转职了（荆棘盾兵、前线装甲）
    if 行动详情_角色 != 原职业:
        print(文(f">> 只有{原职业}能转职成{新职业}（你现在是{行动详情_角色}）。",
                 f">> Solo el {名(原职业)} puede cambiar a {名(新职业)} (ahora eres {名(行动详情_角色)})."))
        return
    转职(新职业)

def 控制台_跳(参数):
    global 层数, 关卡
    if not 在玩吗():
        return
    if len(参数) < 1 or len(参数) > 2 or 指令数字(参数[0]) is None or (len(参数) == 2 and 指令数字(参数[1]) is None):
        print(文(">> 用法：jump 层 关（层数跟屏幕上显示的一样；关 不写 = 第1关。例：jump 10 9 → 第10层第9关 = 最终头目）",
                 ">> Uso: jump piso sala (el piso como sale en pantalla; sin sala = sala 1. Ej.: jump 10 9 → piso 10, sala 9 = jefe final)"))
        return
    显示的层 = int(指令数字(参数[0]))
    关 = 1
    if len(参数) == 2:
        关 = int(指令数字(参数[1]))
    目标层数 = 游戏层数(当前章节, 显示的层)
    第一 = 本章第一层(当前章节)
    最后 = 本章最后一层(当前章节)
    if 目标层数 < 第一 or 目标层数 > 最后 or 关 < 1 or 关 > 10 or (目标层数 == 最后 and 关 == 10):
        print(文(f">> 跳不过去：{当前章节} 是第{显示层数(当前章节, 第一)}层 ~ 第{显示层数(当前章节, 最后)}层，每层第1~10关（最后一层只有第1~9关）",
                 f">> No puedes saltar ahí: {名(当前章节)} va del piso {显示层数(当前章节, 第一)} al {显示层数(当前章节, 最后)}, salas 1~10 en cada piso (el último piso solo tiene las salas 1~9)"))
        return
    层数 = 目标层数
    关卡 = 关 - 1                                         # 打这一局() 开始下一关的时候会 +1
    print(文(f">> 这一关打完以后，下一关是 {当前章节} 第{显示的层}层第{关}关",
             f">> Cuando acabes esta sala, la siguiente será {名(当前章节)}, piso {显示的层}, sala {关}"))

def 控制台_杀():
    global 敌人_当前生命值
    if not 战斗中:
        print(文(">> 现在没在战斗。", ">> Ahora no estás en combate."))
        return
    敌人_当前生命值 = 0
    print(文(f">> {敌人名字}的生命值变成0了（你这回合行动完它就会倒下；一定输的头目还是会锁血）",
             f">> La vida de {敌人名字文字()} ahora es 0 (caerá cuando acabes tu acción de este turno; los jefes que no se pueden ganar se quedan con 1)"))

def 控制台_祝福次数(参数):
    global 本局祝福次数
    if not 在玩吗():
        return
    if len(参数) != 1 or 指令数字(参数[0]) is None:
        print(文(">> 用法：blessings 数量（例：blessings 10）", ">> Uso: blessings cantidad (ej.: blessings 10)"))
        return
    本局祝福次数 = max(0, int(指令数字(参数[0])))
    print(文(f">> 本局祝福次数：{本局祝福次数}（下一次祝福是第{本局祝福次数 + 1}次）",
             f">> Bendiciones en esta partida: {本局祝福次数} (la próxima será la {本局祝福次数 + 1}.ª)"))

def 控制台_路线():
    if not 在玩吗():
        return
    print(文(f">> {天赋路线文字()} → {路线文字(当前路线())}（某一种 ≥{路线最少天赋}个，而且比另外两种都多）",
             f">> {天赋路线文字()} → {路线文字(当前路线())} (hace falta que un tipo tenga ≥{路线最少天赋} y más que los otros dos)"))
    print(文(f">> 七魄：{七魄数量()}/{len(七魄)}（第九章要齐）| 成神的道路：{天赋数量('成神的道路')}/{成神的道路总数()}（第八章要齐）",
             f">> 7 Emociones: {七魄数量()}/{len(七魄)} (en el capítulo 9 hacen falta todas) | Camino a la Divinidad: {天赋数量('成神的道路')}/{成神的道路总数()} (en el capítulo 8 hace falta todo)"))

def 控制台_测试模式():
    global 测试_解锁全部章节
    测试_解锁全部章节 = not 测试_解锁全部章节                  # not = 反过来：开 → 关，关 → 开
    print(文(f">> 测试模式：{开关文字(测试_解锁全部章节)}（所有章节都能选、所有天赋都会出现）",
             f">> Modo prueba: {开关文字(测试_解锁全部章节)} (puedes elegir todos los capítulos y salen todos los talentos)"))

def 控制台_解锁(参数):
    # 修改（语言）：名字 → unlock chapter 编号（编号跟选择章节里的一样）/ unlock talent 编号（编号跟 talent 一样）/ unlock all
    # 新加：unlock class 编号（1 狂战士，2 重装骑士）：永久解锁进阶职业（以后满足条件点一次满级被动就直接转职）
    if not 选了存档吗():
        return
    if len(参数) == 1 and 参数[0].lower() == "all":
        for 章节 in 章节列表:
            解锁章节(章节)
        for 天赋 in 需要解锁的天赋:
            解锁天赋(天赋)
        for 职业名 in 进阶职业:
            解锁职业(职业名)
    elif len(参数) >= 2 and 参数[0].lower() == "chapter" and 指令编号们(参数[1:], len(章节显示顺序)) is not None:
        for 位置 in 指令编号们(参数[1:], len(章节显示顺序)):
            解锁章节(章节显示顺序[位置])
    elif len(参数) >= 2 and 参数[0].lower() == "talent" and 指令编号们(参数[1:], len(天赋名字列表)) is not None:
        for 位置 in 指令编号们(参数[1:], len(天赋名字列表)):
            解锁天赋(天赋名字列表[位置])
    elif len(参数) >= 2 and 参数[0].lower() == "class" and 指令编号们(参数[1:], len(进阶职业)) is not None:
        for 位置 in 指令编号们(参数[1:], len(进阶职业)):
            解锁职业(进阶职业[位置])
    else:
        print(文(">> 用法：unlock chapter 编号（例：unlock chapter 7 = 第七章）/ unlock talent 编号（例：unlock talent 9 = 地魂）/ unlock class 编号（例：unlock class 1 = 狂战士）/ unlock all = 全部",
                 ">> Uso: unlock chapter número (ej.: unlock chapter 7 = capítulo 7) / unlock talent número (ej.: unlock talent 9 = Alma) / unlock class número (ej.: unlock class 1 = Berserker) / unlock all = todo"))
        print(文(f"   章节：{编号列表(章节显示顺序)}", f"   Capítulos: {编号列表(章节显示顺序)}"))
        print(文("   天赋：编号跟 talent 的一样（/help 里看）", "   Talentos: los mismos números que talent (míralos en /help)"))
        print(文(f"   职业：{编号列表(进阶职业)}", f"   Clases: {编号列表(进阶职业)}"))
        return
    保存进度(当前存档编号)
    print(文(">> 进度存好了（已经解锁过的不会再说一次）。", ">> Progreso guardado (lo que ya estaba desbloqueado no se vuelve a avisar)."))

def 控制台_结局(参数):
    # 修改（语言）：编号 1~11（看 结局名字列表：11 = 结局10（前一半）），可以写范围、all
    if not 选了存档吗():
        return
    位置们 = 指令编号们(参数, len(结局名字列表))
    if len(参数) == 0 or 位置们 is None:
        print(文(">> 用法：ending 编号……（1-7 = 1到7；all = 全部。例：ending 7）", ">> Uso: ending número... (1-7 = del 1 al 7; all = todos. Ej.: ending 7)"))
        print(f"   {编号列表(结局名字列表)}")
        return
    for 位置 in 位置们:
        if 结局名字列表[位置] not in 已看过的结局:
            已看过的结局.append(结局名字列表[位置])
    检查解锁()                                            # 看过的结局变了，可能会解锁新章节
    保存进度(当前存档编号)
    print(文(f">> 已看过的结局：{名单(已看过的结局)}", f">> Finales vistos: {名单(已看过的结局)}"))

def 控制台_打完(参数):
    # 修改（语言）：章节 → 编号（跟选择章节里的一样：1 第一章 …… 9 第九章 阴、10 第九章 阳、11 第九章 和）
    if not 选了存档吗():
        return
    位置们 = 指令编号们(参数, len(章节显示顺序))
    if len(参数) == 0 or 位置们 is None:
        print(文(">> 用法：finish 编号……（例：finish 3 = 第三章、finish 9 = 第九章 阴；all = 全部）",
                 ">> Uso: finish número... (ej.: finish 3 = capítulo 3, finish 9 = capítulo 9 Yin; all = todos)"))
        print(文(f"   章节：{编号列表(章节显示顺序)}", f"   Capítulos: {编号列表(章节显示顺序)}"))
        return
    for 位置 in 位置们:
        if 章节显示顺序[位置] not in 已打完的章节:
            已打完的章节.append(章节显示顺序[位置])
    检查解锁()
    保存进度(当前存档编号)
    print(文(f">> 已打完的章节：{名单(已打完的章节)}", f">> Capítulos completados: {名单(已打完的章节)}"))

def 控制台_快照(参数):
    # 修改（语言）：快照 存 名字 → snapshot save 编号（1~4，列表里有写）；快照 清空 → snapshot clear
    if len(参数) == 0:
        print(文("快照：", "Instantáneas:"))
        for 编号 in range(len(快照_名字)):
            快照 = 已存的快照[编号]
            if 快照 == "":
                快照 = 文("（还没存）", "(sin guardar)")
            else:
                快照 = 快照文字(快照)
            用在 =文(f"{快照_用在章节[编号]} 第{显示层数(快照_用在章节[编号], 快照_用在层数[编号])}层",
                      f"{名(快照_用在章节[编号])}, piso {显示层数(快照_用在章节[编号], 快照_用在层数[编号])}")
            print(文(f"    {编号 + 1} {快照_名字[编号]}（用在 {用在}）：{快照}",
                     f"    {编号 + 1} {名(快照_名字[编号])} (se usa en {用在}): {快照}"))
        return
    if len(参数) == 1 and 参数[0].lower() == "clear":
        if not 选了存档吗():
            return
        for 编号 in range(len(快照_名字)):
            已存的快照[编号] = ""
        保存进度(当前存档编号)
        print(文(">> 快照全部删掉了。", ">> Instantáneas borradas."))
        return
    名字 = None
    if len(参数) == 2 and 参数[0].lower() == "save":
        名字 = 第几个(参数[1], 快照_名字)
    if 名字 is not None:
        if not 选了存档吗() or not 在玩吗():
            return
        编号 = 快照_名字.index(名字)
        已存的快照[编号] = 现在的快照()
        保存进度(当前存档编号)
        print(文(f">> 存好了：{名字} = {已存的快照[编号]}", f">> Guardada: {名(名字)} = {快照文字(已存的快照[编号])}"))
        return
    print(文(f">> 用法：snapshot（看）/ snapshot save 编号（{编号列表(快照_名字)}）/ snapshot clear",
             f">> Uso: snapshot (ver) / snapshot save número ({编号列表(快照_名字)}) / snapshot clear"))

def 快照文字(快照):
    # 新加（语言）：显示用：快照最前面是职业的名字（中文），西班牙语要翻译一下："战士,250,……" → "Guerrero,250,……"
    if 语言 == "西班牙语" and "," in 快照:
        拆开 = 快照.split(",", 1)
        return 名(拆开[0].strip()) + "," + 拆开[1]
    return 快照

def 控制台_存档():
    if not 选了存档吗() or not 在玩吗():
        return
    保存存档(当前存档编号)
    保存进度(当前存档编号)

关卡 = 0
层数 = 第一层                   # 修改：从第0层开始

# 修改：原来输入1以外的东西，游戏什么都不说就直接关掉了；现在用 try/except 检查，输错了会让你重新输
#       现在只有冒险模式，所以只有输入1才会往下走（选择模式 也从文字 "1" 变成了数字 1）
# 修改：从文件最上面挪到了这里（输入完要马上清屏，要等 清屏() 写好了才能用）
# 修改（控制台）：开发者模式的话先说一声怎么用控制台；input → 读输入
# 新加（语言）：最先问用哪种语言（中文 / 西班牙语），以后在战斗的 [0] 设置 里也能换
选择语言()
if 开发者模式:
    print(文(">> 开发者模式：任何要输入的地方都能输 / 开头的指令（例：/help 看全部指令；只输入 / 进入控制台）",
             ">> Modo desarrollador: en cualquier sitio donde escribas puedes poner comandos que empiecen por / (ej.: /help para verlos todos; solo / para entrar en la consola)"))
while True:
    try:
        选择模式 = int(读输入(文("""
        当前可选游戏模式：
        [1] 冒险模式(单人)
        [?] 敬请期待
             """, """
        Modos de juego disponibles:
        [1] Modo aventura (un jugador)
        [?] Próximamente
             """)))
        if 选择模式 == 1:
            清屏()
            break
        print(文(">> 这个模式还没开放，敬请期待~", ">> Este modo todavía no está disponible, ¡próximamente~!"))
    except ValueError:
        print(文(">> 输入项目并非数字。请输入给予的选项并输入其对应的数字",
                 ">> Eso no es un número. Escribe el número de una de las opciones que salen"))

if 选择模式 == 1:               # 修改：选择模式 现在是数字（上面用 int() 转过了）

    # 修改：外面又套了一层 while True：在设置里退出存档以后，会回到选择存档（不用重新打开游戏）
    #       想关掉游戏就在选择存档里选 [0] 退出游戏
    # 修改：死了、打完一章 → 回到选择章节（还是同一个存档，像以撒一样再开一局）
    #       一关一关打的部分挪到了 打这一局() 里面（在 章节 那一部分）
    while True:
        选择存档()          # 选一个存档 → 继续这一局（读档），或者选章节开始新的一局
        while True:
            要退出存档 = False
            结果 = 打这一局()                   # "死了" / "打完了" / "剧情杀" / "退出存档"（修改（第四步）：多了 剧情杀，跟 打完了 一样回到选择章节）
            这一局在打 = False                  # 新加（控制台）：这一局结束了（或者退出存档了）
            if 结果 == "退出存档" or (结果 == "死了" and not 死亡后清空存档):
                break                           # 回到选择存档（死了不清空存档的话，在那里可以「继续这一局」，从上一关重新开始）
            if not 选择章节():                  # 修改：这里原来有 清屏()（要按回车），现在不用了：结果和选择章节一起显示
                break                           # 在选择章节里按了 [0] 返回 → 回到选择存档